import { createServerClient } from '@supabase/ssr';
import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import crossFetch from 'cross-fetch';

export const dynamic = 'force-dynamic';

export async function POST(request: Request) {
  const cookieStore = await cookies();

  const allCookies = cookieStore.getAll();
  for (const cookie of allCookies) {
    if (cookie.name.startsWith("sb-")) {
      cookieStore.delete(cookie.name);
    }
  }

  return NextResponse.json({ status: "ok" });
}

"use client";
import React, { useEffect, useState } from "react";
import { Typography } from "@/components/ui";
import { Globe, Users, Building, MapPin } from "lucide-react";
import InternshipCard from "@/components/InternshipCard";

interface CompanyClientProps {
  employerId: string;
}

export default function CompanyClient({ employerId }: CompanyClientProps) {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function fetchData() {
      try {
        const res = await fetch(
          `http://localhost:8000/api/companies/${employerId}`,
        );
        if (!res.ok) throw new Error("Failed to load company");
        const json = await res.json();
        setData(json);
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, [employerId]);

  if (loading)
    return (
      <div className="p-12 text-center text-slate-500">Loading company...</div>
    );
  if (error)
    return <div className="p-12 text-center text-red-500">{error}</div>;
  if (!data) return null;

  const { company, internships } = data;

  return (
    <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in duration-500">
      {/* Hero Section */}
      <div className="bg-white rounded-3xl border border-slate-100/60 overflow-hidden shadow-[0_4px_20px_rgba(0,0,0,0.02)] relative">
        <div className="h-56 relative bg-slate-100">
          {company.company_banner_url ? (
            <img
              src={company.company_banner_url}
              alt={`${company.full_name} banner`}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-r from-brand to-brand/70 relative">
              <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
            </div>
          )}
        </div>
        <div className="px-10 pb-10 relative">
          <div className="flex flex-col md:flex-row md:items-end md:justify-between -mt-20 sm:-mt-24 mb-8 gap-4">
            <div className="flex items-end gap-6">
              <div className="w-32 h-32 rounded-2xl bg-white border-4 border-white shadow-md overflow-hidden flex items-center justify-center">
                {company.company_logo_url ? (
                  <img
                    src={company.company_logo_url}
                    alt={company.full_name}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <Building className="w-12 h-12 text-slate-300" />
                )}
              </div>
              <div className="mb-2">
                <Typography
                  variant="h2"
                  weight="bold"
                  className="text-slate-900 tracking-tight"
                >
                  {company.full_name}
                </Typography>
                <div className="flex items-center gap-4 mt-3 text-slate-500 text-sm font-medium">
                  {company.industry && (
                    <span className="flex items-center gap-1.5 bg-slate-50 border border-slate-100 px-4 py-1.5 rounded-full text-slate-600 shadow-sm">
                      {company.industry}
                    </span>
                  )}
                  {company.company_website && (
                    <a
                      href={
                        company.company_website.startsWith("http")
                          ? company.company_website
                          : `https://${company.company_website}`
                      }
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center gap-1.5 hover:text-brand transition-colors bg-brand/5 text-brand px-4 py-1.5 rounded-full"
                    >
                      <Globe className="w-4 h-4" /> Website
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
            <div className="md:col-span-2 space-y-10">
              {company.company_description && (
                <section>
                  <Typography
                    variant="h4"
                    weight="bold"
                    className="text-slate-800 mb-4"
                  >
                    About Us
                  </Typography>
                  <Typography
                    variant="body1"
                    className="text-slate-600 leading-relaxed whitespace-pre-wrap"
                  >
                    {company.company_description}
                  </Typography>
                </section>
              )}
              {company.culture && (
                <section>
                  <Typography
                    variant="h4"
                    weight="bold"
                    className="text-slate-800 mb-4"
                  >
                    Culture & Perks
                  </Typography>
                  <Typography
                    variant="body1"
                    className="text-slate-600 leading-relaxed whitespace-pre-wrap"
                  >
                    {company.culture}
                  </Typography>
                </section>
              )}
            </div>

            <div className="bg-white rounded-2xl p-8 border border-slate-100/60 shadow-[0_4px_20px_rgba(0,0,0,0.02)] h-fit space-y-5">
              <Typography
                variant="h5"
                weight="bold"
                className="text-slate-800 mb-6"
              >
                Company Overview
              </Typography>
              <div className="flex items-center gap-4 text-slate-600">
                <div className="w-10 h-10 rounded-full bg-brand/5 flex items-center justify-center text-brand">
                  <Building className="w-5 h-5" />
                </div>
                <span className="font-medium">
                  {company.industry || "Industry unlisted"}
                </span>
              </div>
              <div className="flex items-center gap-4 text-slate-600">
                <div className="w-10 h-10 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-600">
                  <Users className="w-5 h-5" />
                </div>
                <span className="font-medium">Verified Employer</span>
              </div>
              <div className="flex items-center gap-4 text-slate-600">
                <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600">
                  <MapPin className="w-5 h-5" />
                </div>
                <span className="font-medium">Global / Remote</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Internships List */}
      <div className="pt-4">
        <Typography
          variant="h3"
          weight="bold"
          className="text-slate-800 mb-6 tracking-tight"
        >
          Open Internships
        </Typography>
        {internships.length === 0 ? (
          <div className="text-center py-16 bg-white rounded-2xl border border-slate-100/60 shadow-[0_4px_20px_rgba(0,0,0,0.02)]">
            <Typography variant="body1" className="text-slate-500">
              No open roles at the moment.
            </Typography>
          </div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {internships.map((job: any) => (
              <InternshipCard key={job.id} internship={job} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, Suspense } from "react";
import { useSearchParams } from "next/navigation";
import { Typography } from "@/components/ui";

function CVViewerContent() {
  const searchParams = useSearchParams();
  const url = searchParams ? searchParams.get("url") : null;
  const name = searchParams ? (searchParams.get("name") || "Student CV") : "Student CV";

  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Set the document title cleanly to the student's name
    document.title = name;

    // Slight delay to allow iframe to initiate painting before removing loader
    if (url) {
      setTimeout(() => setIsLoading(false), 800);
    }
  }, [name, url]);

  if (!url) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <Typography variant="h6" color="muted">Invalid CV Link Provided</Typography>
      </div>
    );
  }

  // We must strip any legacy '?download=' queries from the database URL, so Supabase doesn't force a download.
  let cleanUrl: string | null = url;
  try {
    const parsed = new URL(url);

    // SECURITY PATCH: Explicitly enforce that the URL is 
    // strictly targeting our Supabase database domain to prevent XSS iframe injections.
    if (!parsed.origin.includes("supabase.co") || parsed.protocol !== "https:") {
      console.warn("Security Alert: Blocked untrusted iframe URL injection.", url);
      cleanUrl = null;
    } else {
      parsed.searchParams.delete("download");
      cleanUrl = parsed.toString();
    }
  } catch (e) {
    cleanUrl = null;
  }

  // Double check if the security validation wiped the URL
  if (!cleanUrl) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <Typography variant="h6" className="text-red-600 font-bold">Security Error: Untrusted URL Source Blocked</Typography>
      </div>
    );
  }

  // We append #view=FitH to the Supabase URL to force the browser's native PDF viewer to fill the width
  const viewerUrl = `${cleanUrl}#view=FitH`;

  return (
    <div className="w-screen h-screen overflow-hidden relative bg-[#333]">
      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-slate-50 z-10">
          <div className="text-center space-y-4">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto"></div>
            <Typography variant="body1" weight="semibold" color="muted">Securely loading {name}...</Typography>
          </div>
        </div>
      )}
      <iframe 
        src={viewerUrl} 
        className="w-full h-full border-none" 
        title={`${name} PDF Viewer`}
        onLoad={() => setIsLoading(false)}
      />
    </div>
  );
}

export default function CVViewer() {
  return (
    <Suspense fallback={
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    }>
      <CVViewerContent />
    </Suspense>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import PostInternshipView from "./post/PostInternshipView";
import {
  Button,
  Stack,
  Typography,
  Divider,
} from "@/components/ui";
import { FiLogOut, FiPieChart, FiPlusSquare } from "react-icons/fi";
import AnalyticsView from "./AnalyticsView";

export default function DashboardClient({ session }: { session: any }) {
  const [activeTab, setActiveTab] = useState("analytics");
  const [categories, setCategories] = useState<{ label: string; value: number }[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    if (!session?.user) {
      router.push("/");
      return;
    }

    const fetchData = async () => {
      try {
        setLoading(true);
        const { data, error } = await supabase.from("internships").select("category");

        if (!error && data) {
          const counts: Record<string, number> = {};
          data.forEach((item) => {
            const category = item.category || "Unknown";
            counts[category] = (counts[category] || 0) + 1;
          });
          const categoryArray = Object.entries(counts).map(([label, value]) => ({
            label,
            value,
          }));
          setCategories(categoryArray);
        }
      } catch (err) {
        console.error("Dashboard fetch error:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [session, router]);

  const [isLoggingOut, setIsLoggingOut] = useState(false);

  const handleLogout = async () => {
    if (isLoggingOut) return;
    setIsLoggingOut(true);

    try {
      // 1. Sign out from Supabase client (requires active session token in storage)
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("Supabase signOut error:", err);
    }

    try {
      // 2. Clear cookies on the server
      await fetch("/api/auth/logout", { method: "POST" });
    } catch (err) {
      console.warn("Server cookie logout error:", err);
    }

    // 3. Clear other local storage
    localStorage.clear();

    router.push("/");
  };

  if (!session?.user || loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8fafc]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-brand"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] p-6 md:p-10">
      <div className="max-w-7xl mx-auto space-y-10">
        <header className="flex justify-between items-center bg-white/60 backdrop-blur-xl p-6 rounded-[32px] border border-white shadow-xl shadow-indigo-50/50">
          <Stack direction="row" align="center" spacing={4}>
            <div className="w-12 h-12 bg-gradient-to-br from-brand to-brand-secondary rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <img src="/favicon.ico" alt="Logo" className="w-8 h-8 opacity-90" />
            </div>
            <div>
              <Typography variant="h4" weight="bold">Admin Portal</Typography>
              <Typography variant="caption" weight="semibold" color="muted">Manage your platform ecosystem</Typography>
            </div>
          </Stack>

          <Button
            variant="outline"
            size="sm"
            onClick={handleLogout}
            disabled={isLoggingOut}
            leftIcon={isLoggingOut ? <div className="w-4 h-4 rounded-full border-2 border-red-500 border-t-transparent animate-spin" /> : <FiLogOut className="w-4 h-4" />}
            className={`rounded-xl transition-all font-bold ${isLoggingOut ? 'opacity-50 cursor-not-allowed border-red-200 text-red-500 bg-red-50' : 'border-slate-200 hover:border-red-200 hover:text-red-500 hover:bg-red-50'}`}
          >
            {isLoggingOut ? "Logging out..." : "Logout"}
          </Button>
        </header>

        <Stack direction="row" spacing={4} className="flex-wrap gap-y-4">
          <Button
            variant={activeTab === "analytics" ? "solid" : "outline"}
            onClick={() => setActiveTab("analytics")}
            leftIcon={<FiPieChart className="w-5 h-5" />}
            className={`px-8 h-14 rounded-2xl font-bold transition-all duration-300 ${
              activeTab === "analytics" 
                ? "shadow-xl shadow-indigo-100" 
                : "bg-white border-slate-100 text-slate-500 hover:border-brand hover:text-brand"
            }`}
          >
            Analytics Overview
          </Button>
          <Button
            variant={activeTab === "post" ? "solid" : "outline"}
            onClick={() => setActiveTab("post")}
            leftIcon={<FiPlusSquare className="w-5 h-5" />}
            className={`px-8 h-14 rounded-2xl font-bold transition-all duration-300 ${
              activeTab === "post" 
                ? "shadow-xl shadow-indigo-100" 
                : "bg-white border-slate-100 text-slate-500 hover:border-brand hover:text-brand"
            }`}
          >
            Post Internship
          </Button>
        </Stack>

        <Divider className="opacity-40" />

        <main className="animate-in fade-in slide-in-from-bottom-6 duration-500 fill-mode-both">
          {activeTab === "analytics" && <AnalyticsView categories={categories} />}
          {activeTab === "post" && <PostInternshipView />}
        </main>
      </div>
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import { Button, Stack, Typography, Divider } from "@/components/ui";
import { LogOut, Search, Command } from "lucide-react";
import { cx } from "@/utils/cx";
import SearchOverlay from "@/components/SearchOverlay";

import DashboardShell from "@/components/DashboardShell";

export default function AdminClient({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const activeTab = searchParams?.get("tab") || "overview";
  const [showSearch, setShowSearch] = useState(false);

  const tabs = [
    { key: "overview", label: "Overview" },
    { key: "analytics", label: "Analytics" },
    { key: "post", label: "Post Internship" },
    { key: "manage", label: "Manage Platform" },
  ];

  const handleTabChange = (key: string) => {
    router.push(`/dashboard/admin?tab=${key}`);
  };

  const [isLoggingOut, setIsLoggingOut] = useState(false);

  const handleLogout = async () => {
    if (isLoggingOut) return;
    setIsLoggingOut(true);

    try {
      // 1. Sign out from Supabase client (requires active session token in storage)
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("Supabase signOut error:", err);
    }

    try {
      // 2. Clear cookies on the server
      await fetch("/api/auth/logout", { method: "POST" });
    } catch (err) {
      console.warn("Server cookie logout error:", err);
    }

    // 3. Clear other local storage
    localStorage.clear();

    router.refresh();
    router.push("/");
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] p-6 md:p-10">
      {showSearch && <SearchOverlay onClose={() => setShowSearch(false)} />}
      <div className="max-w-7xl mx-auto">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 bg-white/80 backdrop-blur-md p-6 rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <Stack direction="row" align="center" spacing={4}>
            <img src="/favicon.ico" alt="PAU Logo" className="w-10 h-10 rounded-xl shadow-sm" />
            <Typography variant="h4" weight="bold">Admin Control Center</Typography>
          </Stack>

          <div className="flex-1 max-w-md w-full relative group">
            <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
              <Search className="h-4 w-4 text-slate-400 group-hover:text-indigo-500 transition-colors" />
            </div>
            <input
              type="text"
              placeholder="Super search..."
              readOnly
              onClick={() => setShowSearch(true)}
              className="block w-full pl-12 pr-12 py-3 bg-slate-50/50 border border-slate-100 rounded-2xl text-sm placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all cursor-pointer hover:bg-slate-50 shadow-inner"
            />
          </div>

          <Button
            variant="outline"
            size="sm"
            onClick={handleLogout}
            disabled={isLoggingOut}
            leftIcon={isLoggingOut ? <div className="w-4 h-4 rounded-full border-2 border-red-500 border-t-transparent animate-spin" /> : <LogOut className="w-4 h-4" />}
            className={`rounded-xl transition-all ${isLoggingOut ? "opacity-50 cursor-not-allowed border-red-200 text-red-500 bg-red-50" : "border-slate-200 hover:border-red-200 hover:text-red-500 hover:bg-red-50"}`}
          >
            {isLoggingOut ? "Logging out..." : "Logout"}
          </Button>
        </header>

        <Divider className="mb-10 opacity-50" />

        <Stack direction="row" spacing={3} className="flex-wrap gap-y-3 mb-10">
          {tabs.map((tab) => (
            <Button
              key={tab.key}
              variant={activeTab === tab.key ? "solid" : "outline"}
              onClick={() => handleTabChange(tab.key)}
              className={cx(
                "px-8 rounded-xl font-bold transition-all duration-300",
                activeTab === tab.key 
                  ? "shadow-sm border-brand" 
                  : "bg-white border-slate-100 text-slate-600 hover:border-brand hover:text-brand"
              )}
            >
              {tab.label}
            </Button>
          ))}
        </Stack>

        <main className="animate-in fade-in slide-in-from-bottom-8 duration-500">
          {children}
        </main>
      </div>
    </div>
  );
}

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { Typography, Card, CardContent } from "@/components/ui";
import {
  FiUsers,
  FiBriefcase,
  FiFileText,
  FiCalendar,
  FiUserPlus,
  FiActivity,
} from "react-icons/fi";
import crossFetch from "cross-fetch";

async function getAdminSupabase() {
  const cookieStore = await cookies();
  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: { fetch: crossFetch },
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll() {},
      },
    },
  );
}

