  },
  {
    key: "new_users_today",
    label: "New Users Today",
    icon: <FiUserPlus className="w-8 h-8" />,
    accent: "bg-amber-500",
    bg: "bg-amber-50/50",
  },
];

export async function AdminStatsSection() {
  const BACKEND_URL =
    process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:8000";

  // Fetch stats from the optimized backend endpoint
  const supabase = await getAdminSupabase();
  const {
    data: { session },
  } = await supabase.auth.getSession();

  let stats: any = {};
  try {
    const res = await fetch(`${BACKEND_URL}/admin/stats`, {
      cache: "no-store",
      headers: {
        Authorization: `Bearer ${session?.access_token}`,
        "X-Admin-Security": "streaming-fetch",
      },
    });
    stats = await res.json();
  } catch (err) {
    console.error("Admin stats fetch failed", err);
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
      {metricCards.map((card, index) => (
        <Card
          key={card.key}
          className="group transition-all duration-300 hover:shadow-2xl hover:shadow-indigo-100 border-slate-100 overflow-hidden"
        >
          <CardContent className={`p-8 ${card.bg} relative`}>
            <div
              className={`absolute top-0 right-0 w-32 h-32 ${card.accent} opacity-[0.03] rounded-bl-full transform translate-x-8 -translate-y-8 group-hover:scale-110 transition-transform duration-500`}
            />
            <div className="relative z-10 space-y-6">
              <div
                className={`w-14 h-14 ${card.accent} text-white rounded-2xl flex items-center justify-center shadow-lg shadow-current/20 group-hover:scale-110 transition-transform duration-300`}
              >
                {card.icon}
              </div>
              <div className="space-y-1">
                <Typography
                  variant="h1"
                  weight="extrabold"
                  className="text-slate-900 tracking-tight"
                >
                  {stats[card.key]?.toLocaleString() ?? 0}
                </Typography>
                <Typography
                  variant="body2"
                  weight="bold"
                  color="muted"
                  className="uppercase tracking-widest text-[10px]"
                >
                  {card.label}
                </Typography>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

"use client";

import React from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

interface AnalyticsChartsProps {
  internshipStats: any[];
}

export default function AnalyticsCharts({ internshipStats }: AnalyticsChartsProps) {
  return (
    <div className="h-[300px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={(internshipStats || []).slice(0, 10)} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
          <XAxis 
            dataKey="title" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fontSize: 12, fill: '#94a3b8' }} 
            tickFormatter={(value) => value && value.length > 15 ? value.substring(0, 15) + '...' : value}
          />
          <YAxis 
            axisLine={false} 
            tickLine={false} 
            tick={{ fontSize: 12, fill: '#94a3b8' }}
          />
          <Tooltip 
            cursor={{ fill: '#f8fafc' }}
            contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)' }}
          />
          <Bar dataKey="applications" fill="var(--brand)" radius={[6, 6, 0, 0]} barSize={40} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Typography,
  Stack,
  Button,
  Input,
  Textarea,
  Badge,
} from "@/components/ui";
import { supabase } from "@/lib/supabaseClient";
import { FiPlus, FiCheckCircle, FiAlertCircle } from "react-icons/fi";

const CATEGORIES = [
  "Technology",
  "Finance",
  "Consulting",
  "Healthcare",
  "Design",
  "Marketing",
];

const INTERESTS_OPTIONS = [
  "Software Development",
  "Data Science",
  "Engineering",
  "Business",
  "Consulting",
  "Finance",
  "Design",
  "Marketing",
  "Research",
  "Healthcare",
  "UX/UI",
  "Product Management",
  "Analytics",
  "Machine Learning",
];

export default function PostInternshipView() {
  const [company, setCompany] = useState("");
  const [role, setRole] = useState("");
  const [field, setField] = useState("");
  const [category, setCategory] = useState("");
  const [description, setDescription] = useState("");
  const [requirements, setRequirements] = useState("");
  const [interests, setInterests] = useState<string[]>([]);
  const [deadline, setDeadline] = useState("");
  const [linkedin, setLinkedin] = useState("");
  const [notification, setNotification] = useState<{ message: string; type: "success" | "error" | null }>({
    message: "",
    type: null,
  });
  const [isLoading, setIsLoading] = useState(false);

  const toggleInterest = (item: string) => {
    setInterests((prev) =>
      prev.includes(item) ? prev.filter((i) => i !== item) : [...prev, item]
    );
  };

  const handlePostInternship = async () => {
    if (
      !company ||
      !role ||
      !field ||
      !category ||
      !description ||
      !requirements ||
      !deadline ||
      interests.length === 0
    ) {
      setNotification({
        message: "Please fill all required fields and select interests.",
        type: "error",
      });
      setTimeout(() => setNotification({ message: "", type: null }), 4000);
      return;
    }

    setIsLoading(true);

    try {
      const { data: userData } = await supabase.auth.getUser();
      const user = userData?.user ?? null;

      let posterId: string | null = null;
      const { data: adminProfile } = await supabase
        .from("profiles")
        .select("id")
        .eq("is_admin", true)
        .maybeSingle();

      posterId = adminProfile?.id ?? user?.id ?? null;

      const payload = {
        poster_id: posterId,
        company,
        role,
        field,
        category,
        description,
        requirements,
        interests,
        deadline: deadline ? new Date(deadline).toISOString() : null,
        recruiter_link: linkedin || null,
      };

      const { error } = await supabase.from("internships").insert([payload]);

      if (error) throw error;

      setNotification({
        message: "Internship posted successfully!",
        type: "success",
      });
      setTimeout(() => setNotification({ message: "", type: null }), 4000);

      // Clear form
      setCompany("");
      setRole("");
      setField("");
      setCategory("");
      setDescription("");
      setRequirements("");
      setInterests([]);
      setDeadline("");
      setLinkedin("");
    } catch (error: any) {
      console.error("Post internship error:", error);
      setNotification({
        message: error?.message ?? "Failed to post internship. Try again.",
        type: "error",
      });
      setTimeout(() => setNotification({ message: "", type: null }), 4000);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-500">
      <div className="bg-white rounded-[32px] p-8 md:p-12 border border-slate-100 shadow-xl shadow-indigo-50/50 space-y-10 relative overflow-hidden">
        {/* Decorative elements */}
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50/50 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-2">
            <Typography variant="h2" weight="bold">Post New Internship</Typography>
            <Typography variant="body1" color="muted">Fill in the details to reach more candidates</Typography>
          </div>
          <div className="w-16 h-16 bg-indigo-50 text-indigo-500 rounded-2xl flex items-center justify-center shadow-inner">
            <FiPlus className="w-8 h-8" />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 relative z-10">
          <Input
            label="Company Name"
            placeholder="Enter company name"
            value={company}
            onChange={(e) => setCompany(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
          <Input
            label="Role Title"
            placeholder="e.g. Software Engineer Intern"
            value={role}
            onChange={(e) => setRole(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
          <Input
            label="Field"
            placeholder="e.g. Engineering"
            value={field}
            onChange={(e) => setField(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
          <div className="space-y-1.5 ml-1">
            <label className="block text-sm font-semibold text-slate-700">Category *</label>
            <select
              className="w-full py-2.5 px-4 rounded-xl border border-transparent bg-slate-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500/20 transition-all text-slate-900"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
            >
              <option value="">Select Category</option>
              {CATEGORIES.map((cat) => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="space-y-8 relative z-10">
          <Textarea
            label="Description"
            placeholder="Detailed job description..."
            rows={4}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
          <Textarea
            label="Requirements (One per line)"
            placeholder="Enter job requirements..."
            rows={4}
            value={requirements}
            onChange={(e) => setRequirements(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
        </div>

        <div className="space-y-6 relative z-10">
          <div className="space-y-2">
            <Typography variant="body2" weight="bold" className="ml-1 text-brand">Related Interests * (Select at least one)</Typography>
            <div className="flex flex-wrap gap-2.5">
              {INTERESTS_OPTIONS.map((option) => {
                const isSelected = interests.includes(option);
                return (
                  <button
                    key={option}
                    onClick={() => toggleInterest(option)}
                    className={`px-4 py-2 rounded-xl text-xs font-bold transition-all duration-300 border ${
                      isSelected
                        ? "bg-brand text-white border-brand shadow-lg shadow-indigo-100 scale-105"
                        : "bg-white text-slate-500 border-slate-100 hover:border-indigo-200 hover:text-indigo-500"
                    }`}
                  >
                    {option}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 relative z-10">
          <Input
            label="Application Deadline"
            type="date"
            value={deadline}
            onChange={(e) => setDeadline(e.target.value)}
            required
            className="bg-slate-50 border-transparent focus:bg-white"
          />
          <Input
            label="LinkedIn URL (Optional)"
            placeholder="https://linkedin.com/jobs/..."
            value={linkedin}
            onChange={(e) => setLinkedin(e.target.value)}
            className="bg-slate-50 border-transparent focus:bg-white"
          />
        </div>

        <div className="pt-6 relative z-10">
          <Button
            onClick={handlePostInternship}
            isLoading={isLoading}
            className="w-full h-14 rounded-2xl shadow-xl shadow-indigo-100 hover:shadow-indigo-200 text-lg font-bold"
          >
            Publish Internship Post
          </Button>
        </div>
      </div>

      {notification.type && (
        <div className={`fixed bottom-10 left-1/2 -translate-x-1/2 px-8 py-4 rounded-2xl shadow-2xl animate-in fade-in slide-in-from-bottom-5 duration-300 flex items-center gap-4 z-[100] border ${
          notification.type === "success" 
            ? "bg-emerald-50 text-emerald-700 border-emerald-100" 
            : "bg-red-50 text-red-700 border-red-100"
        }`}>
          {notification.type === "success" ? <FiCheckCircle className="w-6 h-6" /> : <FiAlertCircle className="w-6 h-6" />}
          <Typography variant="body1" weight="bold">{notification.message}</Typography>
        </div>
      )}
    </div>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import DashboardShell from "@/components/DashboardShell";

interface DashboardShellWrapperProps {
  children: React.ReactNode;
  userProfile?: any;
}

export default function DashboardShellWrapper({ children, userProfile }: DashboardShellWrapperProps) {
  const [searchQuery, setSearchQuery] = useState("");

  const onSearchChange = (query: string) => {
    setSearchQuery(query);
    // Broadcast search query to children via custom event
    window.dispatchEvent(new CustomEvent("dashboardSearch", { detail: query }));
  };

  useEffect(() => {
    const handleGridSearch = (e: Event) => {
      const query = (e as CustomEvent).detail;
      setSearchQuery(query || "");
    };
    window.addEventListener("gridSearchChange", handleGridSearch);
    return () => window.removeEventListener("gridSearchChange", handleGridSearch);
  }, []);

  return (
    <DashboardShell 
      userProfile={userProfile} 
      searchQuery={searchQuery}
      onSearchChange={onSearchChange}
    >
      {children}
    </DashboardShell>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Stack, Typography } from "@/components/ui";
import { User, Clock, ChevronRight } from "lucide-react";
import Link from "next/link";
import { cx } from "@/utils/cx";

export function EmployerActivityClient({ 
  initialItems, 
  type 
}: { 
  initialItems: any[], 
  type: "applicants" | "logbooks" 
}) {
  const [searchQuery, setSearchQuery] = useState("");

  useEffect(() => {
    const handleGlobalSearch = (e: Event) => {
       const query = (e as CustomEvent).detail;
       setSearchQuery(query || "");
    };
    window.addEventListener("dashboardSearch", handleGlobalSearch);
    return () => window.removeEventListener("dashboardSearch", handleGlobalSearch);
  }, []);

  const filteredItems = initialItems.filter(item => {
    const searchStr = type === "applicants" 
      ? `${item.profiles?.full_name} ${item.internships?.role}`
      : `${item.profiles?.full_name} ${item.date}`;
    return searchStr.toLowerCase().includes(searchQuery.toLowerCase());
  });

  if (filteredItems.length === 0 && searchQuery) {
    return (
      <div className="p-12 text-center bg-slate-50/50 rounded-[40px] border border-dashed border-slate-200">
        <Typography variant="body2" color="muted">No matches for "{searchQuery}"</Typography>
      </div>
    );
  }

  if (initialItems.length === 0) {
    return (
      <div className="p-16 text-center">
         <Typography variant="body2" color="muted">
           {type === "applicants" ? "No candidate leads yet." : "Status clear. No pending logs."}
         </Typography>
      </div>
    );
  }

  return (
    <div className="divide-y divide-slate-50">
      {filteredItems.map((item: any) => (
        <Link 
          key={item.id} 
          href={type === "applicants" ? `/dashboard/employer/internships/${item.internship_id}` : "/dashboard/employer/logbook"} 
          className="block group"
        >
          <div className="p-6 flex items-center justify-between hover:bg-slate-50/50 transition-colors">
            <div className="flex items-center gap-5">
              <div className={cx(
                "w-12 h-12 rounded-2xl flex items-center justify-center transition-colors",
                type === "applicants" 
                  ? "bg-slate-50 text-slate-400 group-hover:bg-brand/5 group-hover:text-brand" 
                  : "bg-indigo-50/50 text-indigo-400 group-hover:bg-indigo-100 group-hover:text-indigo-600"
              )}>
                {type === "applicants" ? <User className="w-6 h-6" /> : <Clock className="w-6 h-6" />}
              </div>
              <div>
                <Typography variant="h6" weight="bold" className="text-slate-900 group-hover:text-brand transition-colors">
                  {item.profiles?.full_name}
                </Typography>
                <Typography variant="caption" className="text-slate-500 font-medium">
                  {type === "applicants" 
                    ? `${item.internships?.role} • ${item.match_score || 0}% Match Score`
                    : `Log entry for ${new Date(item.date).toLocaleDateString()}`}
                </Typography>
              </div>
            </div>
            {type === "applicants" ? (
              <ChevronRight className="text-slate-300 group-hover:text-brand transition-colors" />
            ) : (
              <div className="px-4 py-2 rounded-xl bg-slate-50 text-slate-500 text-[11px] font-bold uppercase tracking-wider group-hover:bg-brand group-hover:text-white transition-all">
                Approve
              </div>
            )}
          </div>
        </Link>
      ))}
    </div>
  );
}

"use client";
import React, { useState } from "react";
import { FiPlus } from "react-icons/fi";
import { Button, Modal, Input, Select, Textarea, Stack, Typography } from "@/components/ui";
import { supabase } from "@/lib/supabaseClient";

export function PostInternshipButton({ employerProfile }: { employerProfile: any }) {
  const [isOpen, setIsOpen] = useState(false);
  const [creating, setCreating] = useState(false);
  const [formData, setFormData] = useState({
    role: "",
    field: "",
    category: "",
    description: "",
    requirements: "",
    tags: "",
    deadline: "",
    link: ""
  });

  const categories = [
    { value: "Remote", label: "Remote" },
    { value: "Hybrid", label: "Hybrid" },
    { value: "On-site", label: "On-site" }
  ];

  const handleCreate = async () => {
    setCreating(true);
    try {
      const { error } = await supabase.from("internships").insert([{
        employer_id: employerProfile.id,
        company: employerProfile.company_name,
        role: formData.role,
        field: formData.field,
        category: formData.category,
        description: formData.description,
        requirements: formData.requirements,
        interests: formData.tags.split(",").map(i => i.trim()),
        deadline: formData.deadline ? new Date(formData.deadline).toISOString() : null,
        recruiter_link: formData.link || null
      }]);
      if (error) throw error;
      setIsOpen(false);
      window.location.reload(); // Refresh to show new internship in streamed list
    } catch (err: any) {
      alert(err.message);
    } finally {
      setCreating(false);
    }
  };

  return (
    <>
      <Button 
        onClick={() => setIsOpen(true)}
        leftIcon={<FiPlus className="w-5 h-5" />}
        className="shadow-lg shadow-indigo-100"
      >
        Post Internship
      </Button>

      <Modal 
        isOpen={isOpen} 
        onClose={() => setIsOpen(false)} 
        title="Create New Internship" 
        size="lg"
        footer={<><Button variant="ghost" onClick={() => setIsOpen(false)}>Cancel</Button> <Button onClick={handleCreate} isLoading={creating}>Publish</Button></>}
      >
        <Stack spacing={6}>
          <Input label="Job Role" value={formData.role} onChange={e => setFormData({...formData, role: e.target.value})} placeholder="e.g. UX Intern" />
          <Select label="Category" options={categories} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} />
          <Textarea label="Description" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} rows={4} />
          <Input label="Tags (comma separated)" value={formData.tags} onChange={e => setFormData({...formData, tags: e.target.value})} placeholder="React, Figma" />
        </Stack>
      </Modal>
    </>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { Stack, Typography, Card, CardContent, Badge, Button } from "@/components/ui";
import { Briefcase, Users, Clock } from "lucide-react";
import Link from "next/link";
import { cx } from "@/utils/cx";

export default function EmployerInternshipListClient({ 
  initialInternships 
}: { 
  initialInternships: any[] 
}) {
  const [searchQuery, setSearchQuery] = useState("");
  const [fieldFilter, setFieldFilter] = useState("All");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  // Extract unique fields and categories for filter pills
  const fields = ["All", ...Array.from(new Set(initialInternships.map(j => j.field)))];
  const categories = ["All", ...Array.from(new Set(initialInternships.map(j => j.category)))];

  useEffect(() => {
    const handleGlobalSearch = (e: Event) => {
       const query = (e as CustomEvent).detail;
       setSearchQuery(query || "");
       setCurrentPage(1); // Reset to first page on search
    };
    window.addEventListener("dashboardSearch", handleGlobalSearch);
    return () => window.removeEventListener("dashboardSearch", handleGlobalSearch);
  }, []);

  const filteredJobs = initialInternships.filter(job => {
    const matchesSearch = `${job.role} ${job.field} ${job.category}`.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesField = fieldFilter === "All" || job.field === fieldFilter;
    const matchesCategory = categoryFilter === "All" || job.category === categoryFilter;
    return matchesSearch && matchesField && matchesCategory;
  });

  // Pagination slicing
  const totalPages = Math.ceil(filteredJobs.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedJobs = filteredJobs.slice(startIndex, startIndex + itemsPerPage);

  const handleFilterChange = (type: "field" | "category", val: string) => {
    if (type === "field") setFieldFilter(val);
    else setCategoryFilter(val);
    setCurrentPage(1);
  };

  return (
    <div className="space-y-8">
      {/* 1. Filter Bar */}
      <div className="space-y-6 bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm">
        <div>
          <Typography variant="subtitle2" weight="bold" className="text-slate-400 uppercase tracking-widest text-[10px] mb-3 ml-1">Filter by Field</Typography>
          <div className="flex flex-wrap gap-2">
            {fields.map(f => (
              <button
                key={f}
                onClick={() => handleFilterChange("field", f)}
                className={cx(
                  "px-4 py-2 rounded-xl text-xs font-bold transition-all border",
                  fieldFilter === f 
                    ? "bg-brand border-brand text-white shadow-lg shadow-brand/20" 
                    : "bg-slate-50 border-slate-100 text-slate-500 hover:border-brand/30 hover:bg-white"
                )}
              >
                {f}
              </button>
            ))}
          </div>
        </div>

        <div>
          <Typography variant="subtitle2" weight="bold" className="text-slate-400 uppercase tracking-widest text-[10px] mb-3 ml-1">Filter by Category</Typography>
          <div className="flex flex-wrap gap-2">
            {categories.map(c => (
              <button
                key={c}
                onClick={() => handleFilterChange("category", c)}
                className={cx(
                  "px-4 py-2 rounded-xl text-xs font-bold transition-all border",
                  categoryFilter === c 
                    ? "bg-slate-900 border-slate-900 text-white shadow-lg shadow-slate-900/20" 
                    : "bg-slate-50 border-slate-100 text-slate-500 hover:border-brand/30 hover:bg-white"
                )}
              >
                {c}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* 2. Results Count */}
      <div className="px-2 flex justify-between items-center">
        <Typography variant="body2" color="muted">
          Showing <span className="text-slate-900 font-bold">{Math.min(filteredJobs.length, startIndex + 1)}-{Math.min(filteredJobs.length, startIndex + itemsPerPage)}</span> of {filteredJobs.length} roles
        </Typography>
        {(fieldFilter !== "All" || categoryFilter !== "All" || searchQuery) && (
          <button 
            onClick={() => { setFieldFilter("All"); setCategoryFilter("All"); }}
            className="text-[11px] font-bold text-brand uppercase tracking-wider hover:underline"
          >
            Clear Filters
          </button>
        )}
      </div>

      {/* 3. Internship Cards */}
      {paginatedJobs.length === 0 ? (
        <div className="p-16 text-center bg-slate-50/50 rounded-[40px] border border-dashed border-slate-200">
           <Typography variant="h6" weight="bold" className="text-slate-900 mb-2">No postings match your selection</Typography>
           <Typography color="muted">Try adjusting your filters or search query.</Typography>
        </div>
      ) : (
        <Stack spacing={4}>
          {paginatedJobs.map((job: any) => (
            <Card key={job.id} className="group p-2 hover:border-brand hover:shadow-xl hover:shadow-indigo-100 transition-all duration-300 border-slate-100">
              <Link href={`/dashboard/employer/internships/${job.id}`}>
                <CardContent className="flex flex-col md:flex-row justify-between items-start md:items-center p-6 gap-6">
                  <div>
                    <Typography variant="h4" weight="bold" className="group-hover:text-brand transition-colors mb-2">{job.role}</Typography>
                    <Stack direction="row" spacing={3} align="center" className="flex-wrap gap-y-2">
                      <Badge variant="primary" size="sm">{job.field}</Badge>
                      <Badge variant="slate" size="sm">{job.category}</Badge>
                      {job.deadline && (
                        <Stack direction="row" spacing={1.5} align="center" className="text-slate-400">
                          <Clock className="w-3.5 h-3.5" />
                          <Typography variant="caption">{new Date(job.deadline).toLocaleDateString()}</Typography>
                        </Stack>
                      )}
                    </Stack>
                  </div>
                  <Button 
                    variant="outline" 
                    size="sm" 
                    className="w-full md:w-auto"
                    rightIcon={<Users className="w-4 h-4" />}
                  >
                    Review {job.applied_internships?.[0]?.count || 0} Applicants
                  </Button>
                </CardContent>
              </Link>
            </Card>
          ))}
        </Stack>
      )}

      {/* 4. Pagination Footer */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-4 pt-6">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
            disabled={currentPage === 1}
            className="text-slate-500 hover:text-brand disabled:opacity-30"
          >
            Previous
          </Button>
          <div className="flex gap-2">
            {[...Array(totalPages)].map((_, i) => (
              <button
                key={i + 1}
                onClick={() => setCurrentPage(i + 1)}
                className={cx(
                  "w-8 h-8 rounded-xl text-xs font-bold transition-all",
                  currentPage === i + 1 ? "bg-brand text-white shadow-md" : "text-slate-400 hover:bg-slate-100"
                )}
              >
                {i + 1}
              </button>
            ))}
          </div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
            disabled={currentPage === totalPages}
            className="text-slate-500 hover:text-brand disabled:opacity-30"
          >
            Next
          </Button>
        </div>
      )}
    </div>
  );
}

