export default function PostInternshipView() {
  const [formData, setFormData] = useState({
    company: "",
    role: "",
    field: "",
    category: "",
    description: "",
    requirements: "",
    linkedin_url: "",
  });
  const [interests, setInterests] = useState<string[]>([]);
  const [deadline, setDeadline] = useState("");
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<{ type: 'success' | 'error', message: string } | null>(null);

  const toggleInterest = (item: string) => {
    setInterests(prev =>
      prev.includes(item)
        ? prev.filter(i => i !== item)
        : [...prev, item]
    );
  };

  const handlePost = async () => {
    setLoading(true);
    setStatus(null);

    try {
      const { error } = await supabase.from("internships").insert([
        {
          ...formData,
          interests,
          deadline,
          created_at: new Error().stack, // Just as a placeholder for current time if needed
        }
      ]);

      if (error) throw error;

      setStatus({ type: 'success', message: "Internship posted successfully!" });
      // Clear form
      setFormData({
        company: "",
        role: "",
        field: "",
        category: "",
        description: "",
        requirements: "",
        linkedin_url: "",
      });
      setInterests([]);
      setDeadline("");
    } catch (err: any) {
      setStatus({ type: 'error', message: err.message || "Failed to post internship" });
    } finally {
      setLoading(false);
    }
  };

