// --- Internship Grid Section ---
export async function InternshipGridSection() {
  const cookieStore = await cookies();
  const devRole = getDevModeRoleFromCookie(
    cookieStore.get("dev_mode_role")?.value,
  );
  const devProfile = getDevModeProfileForRole(devRole);

  if (devRole === "student") {
    return (
      <InternshipGrid
        initialInternships={[
          {
            id: "dev-1",
            company: "PAU Innovation Lab",
            role: "Product Design Intern",
            location: "Lagos, Nigeria",
            field: "Design",
            category: "Design",
            description:
              "Help shape the next cohort of student-facing product experiences.",
            deadline: "2026-09-10",
            interests: ["Product Design", "Research"],
            matchPercentage: 92,
            applicationStatus: "pending",
          },
          {
            id: "dev-2",
            company: "GreenStack",
            role: "Frontend Engineering Intern",
            location: "Remote",
            field: "Engineering",
            category: "Software",
            description:
              "Build polished interfaces for a climate-tech platform.",
            deadline: "2026-08-21",
            interests: ["Software Engineering", "Frontend"],
            matchPercentage: 88,
            applicationStatus: "applied",
          },
        ]}
        userProfile={devProfile ?? { id: "dev-student" }}
      />
    );
  }

  const supabase = await getSupabase();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) return null;

  // Parallelize the three heavy data fetches
  const [internshipsResult, matchesResult, appliedResult] = await Promise.all([
    supabase.from("internships").select("*"),
    supabase
      .from("match_results")
      .select("internship_id, match_score")
      .eq("user_id", user.id),
    supabase
      .from("applied_internships")
      .select("internship_id, status")
      .eq("user_id", user.id),
  ]);

  const internshipsData = internshipsResult.data || [];
  const matches = matchesResult.data || [];
  const applications = appliedResult.data || [];

  const statusMap = new Map(
    applications.map((a) => [a.internship_id, a.status]),
  );

  const internshipsWithMatches = internshipsData.map((internship: any) => ({
    ...internship,
    matchPercentage:
      matches.find((m: any) => m.internship_id === internship.id)
        ?.match_score ?? 0,
    applicationStatus: statusMap.get(internship.id),
  }));

  return (
    <InternshipGrid
      initialInternships={internshipsWithMatches}
      userProfile={{ id: user.id }}
    />
  );
}

"use client";
import React, { useState, useEffect } from "react";
import DashboardShell from "@/components/DashboardShell";

interface DashboardShellWrapperProps {
  children: React.ReactNode;
  userProfile?: any;
}

export default function DashboardShellWrapper({ children, userProfile }: DashboardShellWrapperProps) {
  const [searchQuery, setSearchQuery] = useState("");

  const onSearchChange = (query: string) => {
    setSearchQuery(query);
    // Broadcast search query to children (like InternshipGrid) via custom event
    window.dispatchEvent(new CustomEvent("dashboardSearch", { detail: query }));
  };

  useEffect(() => {
    const handleGridSearch = (e: Event) => {
      const query = (e as CustomEvent).detail;
      setSearchQuery(query || "");
    };
    window.addEventListener("gridSearchChange", handleGridSearch);
    return () => window.removeEventListener("gridSearchChange", handleGridSearch);
  }, []);

  return (
    <DashboardShell 
      userProfile={userProfile} 
      searchQuery={searchQuery}
      onSearchChange={onSearchChange}
    >
      {children}
    </DashboardShell>
  );
}

"use client";
import { useEffect, useState } from "react";
import {
  Box,
  Typography,
  Button,
  TextField,
  Divider,
  Stack,
  CircularProgress,
  List,
  ListItemButton,
  ListItemText,
  Alert,
} from "@mui/material";
import {
  AutoAwesomeOutlined as SparklesIcon,
  Schedule as PendingIcon,
  CheckCircleOutline,
  ErrorOutline as FlaggedIcon,
  PrintOutlined,
} from "@mui/icons-material";
import DashboardShell from "@/components/DashboardShell";
import { authenticatedFetch } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";

interface LogbookEntry {
  id: string;
  date: string;
  activities_raw: string;
  activities_enhanced: string | null;
  status: string;
  employer_id: string;
  feedback_notes?: string;
}

interface LogbookClientProps {
  initialProfile: { id?: string } | null;
  initialApplications: Array<{
    status?: string;
    internship?:
      | {
          poster_id?: string;
          employer_id?: string;
          role?: string;
          company?: string;
        }
      | Array<{
        session: { access_token?: string; user?: { id?: string } } | null;
          employer_id?: string;
          role?: string;
          company?: string;
        }>;
  }>;
  initialEntries: LogbookEntry[];
  session: { user?: { id?: string } } | null;
}

const LogbookClient = ({
  initialProfile,
  initialApplications,
  initialEntries,
  session: initialSession,
}: LogbookClientProps) => {
  const {
    user: authUser,
    profile: authProfile,
    loading: authLoading,
  } = useAuth();
  const [entries, setEntries] = useState<LogbookEntry[]>(initialEntries);
  const [todayEntry, setTodayEntry] = useState<LogbookEntry | null>(null);
  const [selectedEntry, setSelectedEntry] = useState<LogbookEntry | null>(null);
  const [rawText, setRawText] = useState("");
  const [enhancedText, setEnhancedText] = useState("");
  const [isEnhancing, setIsEnhancing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [employerId, setEmployerId] = useState<string | null>(null);
  const [hasStarted, setHasStarted] = useState(false);
  const [internshipDetails, setInternshipDetails] = useState<{
    role?: string;
    company?: string;
  } | null>(null);

  const studentId =
    initialProfile?.id ||
    authProfile?.id ||
    initialSession?.user?.id ||
    authUser?.id;

  useEffect(() => {
    // 1. Process applications from props
    if (initialApplications && initialApplications.length > 0) {
      const acceptedApp = initialApplications.find(
        (a) =>
          a.status?.toLowerCase() === "accepted" ||
          a.status?.toLowerCase() === "approved",
      );
      if (acceptedApp) {
        const internshipData = Array.isArray(acceptedApp.internship)
          ? acceptedApp.internship[0]
          : acceptedApp.internship;
        if (internshipData) {
          const resolvedEmployerId =
            internshipData.poster_id || internshipData.employer_id;
          setHasStarted(true);
          if (resolvedEmployerId) {
            setEmployerId(resolvedEmployerId);
          }
          setInternshipDetails(internshipData);
        }
      }
    }

    // 2. Load History
    if (studentId && !authLoading) {
      const loadHistory = async () => {
        try {
          const data = await authenticatedFetch<{ entries?: LogbookEntry[] }>(
            `/api/logbook/student?student_id=${studentId}`,
            {},
            15000,
            initialSession ?? undefined,
          );
          const fetchedEntries = data.entries || [];
          setEntries(fetchedEntries);
          const todayStr = new Date().toISOString().split("T")[0];
          const todays = fetchedEntries.find((e) => e.date === todayStr);
          if (todays) setTodayEntry(todays);
        } catch (err) {
          console.error("History fetch error:", err);
        }
      };
      loadHistory();
    }
  }, [initialApplications, studentId, authLoading]);

  const selectEntry = (entry: LogbookEntry) => {
    setSelectedEntry(entry);
    setRawText(entry.activities_raw || "");
    setEnhancedText(entry.activities_enhanced || "");
  };

  const handleEnhance = async () => {
    if (!rawText.trim()) return;
    setIsEnhancing(true);
    try {
      const data = await authenticatedFetch<{ enhanced_text?: string }>(
        "/api/logbook/enhance",
        {
          method: "POST",
          body: JSON.stringify({ raw_text: rawText }),
        },
        15000,
        initialSession ?? undefined,
      );
      if (data.enhanced_text) setEnhancedText(data.enhanced_text);
    } catch (err) {
      console.error(err);
    } finally {
      setIsEnhancing(false);
    }
  };

  const handleSubmit = async () => {
    if (!rawText.trim() || !studentId || !employerId) return;
    setIsSubmitting(true);
    try {
      await authenticatedFetch(
        "/api/logbook/entry",
        {
          method: "POST",
          body: JSON.stringify({
            student_id: studentId,
            employer_id: employerId,
            activities_raw: rawText,
            activities_enhanced: enhancedText || null,
          }),
        },
        15000,
        initialSession ?? undefined,
      );
      setSelectedEntry(null);
      setRawText("");
      setEnhancedText("");
      // Refresh list
      const data = await authenticatedFetch<{ entries?: LogbookEntry[] }>(
        `/api/logbook/student?student_id=${studentId}`,
        {},
        15000,
        initialSession ?? undefined,
      );
      setEntries(data.entries || []);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!hasStarted) {
    return (
      <DashboardShell userProfile={initialProfile || authProfile}>
        <Box sx={{ maxWidth: 640, mx: "auto", mt: 8, px: 2 }}>
          <Alert severity="info" sx={{ borderRadius: 2 }}>
            <Typography variant="subtitle1" fontWeight={800} gutterBottom>
              No Internship Active
            </Typography>
            <Typography variant="body2">
              Once your application status is updated to{" "}
              <strong>Accepted</strong>, your logbook will become available
              here.
            </Typography>
          </Alert>
        </Box>
      </DashboardShell>
    );
  }

  return (
    <DashboardShell userProfile={initialProfile || authProfile}>
      <Box sx={{ maxWidth: 800, mx: "auto", py: 8, px: 3 }}>
        <Stack spacing={4} sx={{ mb: 6 }}>
          <Box>
            <Typography
              variant="caption"
              sx={{
                letterSpacing: 2,
                fontWeight: 700,
                color: "primary.main",
                textTransform: "uppercase",
                mb: 1,
                display: "block",
              }}
            >
              SIWES Logbook
            </Typography>
            <Typography
              variant="h4"
              sx={{ fontWeight: 800, letterSpacing: -1, mb: 0.5 }}
            >
              {internshipDetails?.role}
            </Typography>
            <Stack direction="row" alignItems="center" spacing={1}>
              <Typography
                variant="body2"
                color="text.secondary"
                fontWeight={500}
              >
                at
              </Typography>
              <Typography variant="body2" color="text.primary" fontWeight={700}>
                {internshipDetails?.company}
              </Typography>
            </Stack>
          </Box>
          <Divider />

          <Box>
            <Typography
              variant="subtitle2"
              sx={{
                mb: 2,
                color: "text.secondary",
                textTransform: "uppercase",
                letterSpacing: 1,
                fontSize: 11,
              }}
            >
              {(() => {
                const todayStr = new Date().toISOString().split("T")[0];
                if (!selectedEntry || selectedEntry.date === todayStr)
                  return "Today's Entry";
                return `Entry for ${new Date(selectedEntry.date).toLocaleDateString("en-US", { month: "long", day: "numeric" })}`;
              })()}
            </Typography>

            {(() => {
              const todayStr = new Date().toISOString().split("T")[0];
              const isPastEntry = Boolean(
                selectedEntry && selectedEntry.date !== todayStr,
              );
              const isApproved =
                selectedEntry?.status === "approved" ||
                (todayEntry?.status === "approved" && !selectedEntry);

              if (isApproved) {
                return (
                  <Alert
                    icon={<CheckCircleOutline fontSize="small" />}
                    severity="success"
                    sx={{
                      bgcolor: "transparent",
                      border: "1px solid",
                      borderColor: "success.light",
                      borderRadius: 0,
                    }}
                  >
                    This entry has been approved and is locked.
                  </Alert>
                );
              }

              return (
                <Stack spacing={3}>
                  {selectedEntry?.status === "flagged" && (
                    <Alert severity="error" sx={{ borderRadius: 2 }}>
                      <strong>Revision Requested:</strong>{" "}
                      {selectedEntry.feedback_notes ||
                        "Please update and save this entry again."}
                    </Alert>
                  )}
                  {isPastEntry && (
                    <Alert severity="warning" sx={{ borderRadius: 2 }}>
                      This is an entry from a previous day. It is now{" "}
                      <strong>Read Only</strong>.
                    </Alert>
                  )}

                  <Box
                    sx={{
                      border: "1px solid",
                      borderColor: "divider",
                      borderRadius: 2,
                      overflow: "hidden",
                      opacity: isPastEntry ? 0.7 : 1,
                    }}
                  >
                    <TextField
                      fullWidth
                      multiline
                      rows={8}
                      variant="standard"
                      placeholder="Record your progress..."
                      value={rawText}
                      onChange={(e) => setRawText(e.target.value)}
                      disabled={isPastEntry}
                      InputProps={{
                        disableUnderline: true,
                        sx: {
                          fontSize: 15,
                          lineHeight: 1.6,
                          cursor: isPastEntry ? "not-allowed" : "text",
                        },
                      }}
                      sx={{
                        p: 2,
                        bgcolor: isPastEntry ? "grey.50" : "transparent",
                      }}
                    />
                  </Box>

                  {!isPastEntry && (
                    <Stack
                      direction="row"
                      spacing={2}
                      justifyContent="space-between"
                      alignItems="center"
                    >
                      <Button
                        startIcon={
                          isEnhancing ? (
                            <CircularProgress size={14} />
                          ) : (
                            <SparklesIcon />
                          )
                        }
                        onClick={handleEnhance}
                        disabled={isEnhancing || !rawText.trim()}
                        sx={{
                          textTransform: "none",
                          color: "text.secondary",
                          fontSize: 13,
                          borderRadius: 2,
                        }}
                      >
                        AI Enhance
                      </Button>
