          .map((a) => a.internships)
          .filter((job): job is { id: string; role: string; company: string } =>
            Boolean(job),
          );
        setInternships(uniqueJobs);
        if (uniqueJobs.length > 0) setSelectedId(uniqueJobs[0].id);
      } catch (e) {
        console.error("Failed to load targets", e);
      }
    }
    loadTargets();
  }, []);

  const analyzeGap = async () => {
    if (!selectedId) return;
    setLoading(true);
    setError("");
    setAnalysis(null);
    try {
      const { authenticatedFetch } = await import("@/lib/api");
      const data = await authenticatedFetch<{
