                <div className="space-y-3">
                  {analysis.missing_skills?.map((ms, i: number) => (
                    <div
                      key={i}
                      className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl"
                    >
                      <div>
                        <div className="font-semibold text-slate-800 text-sm">
                          {ms.skill}
                        </div>
                        <div className="flex items-center gap-2 text-xs text-slate-500 mt-1">
                          <span
                            className={cx(
                              "px-2 py-0.5 rounded flex items-center gap-1 font-bold",
                              ms.priority === "High"
                                ? "bg-red-100 text-red-700"
                                : ms.priority === "Medium"
                                  ? "bg-amber-100 text-amber-700"
                                  : "bg-slate-200 text-slate-700",
                            )}
                          >
                            <AlertCircle className="w-3 h-3" /> {ms.priority}{" "}
                            Priority
                          </span>
                          <span className="flex items-center gap-1">
                            <Clock className="w-3 h-3" />{" "}
                            {ms.estimated_learning_time}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                  {(!analysis.missing_skills ||
                    analysis.missing_skills.length === 0) && (
                    <span className="text-slate-400 text-sm italic">
                      You have all the required skills!
                    </span>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Send,
  Clock,
  CheckCircle2,
  X,
  Sparkles,
  AlertTriangle,
  Loader2,
  type LucideIcon,
} from "lucide-react";
import { Modal, Textarea } from "@/components/ui";
import { cx } from "@/utils/cx";
import { authenticatedFetch, authenticatedFetchStream } from "@/lib/api";

interface InternshipClientPartsProps {
  internship: { id: string; company?: string; role?: string };
  hasApplied: boolean;
  applicationStatus: string | null;
  matchingSkills: string[];
  missingSkills: string[];
  userId: string;
  studentEmail?: string;
}

export default function InternshipClientParts({
  internship,
  hasApplied: initialHasApplied,
  applicationStatus,
  matchingSkills,
  missingSkills,
  userId,
  studentEmail,
}: InternshipClientPartsProps) {
  const [hasApplied, setHasApplied] = useState(initialHasApplied);
  const [isApplyModalOpen, setApplyModalOpen] = useState(false);
  const [isCvReviewModalOpen, setCvReviewModalOpen] = useState(false);
  const [coverLetter, setCoverLetter] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDrafting, setIsDrafting] = useState(false);
  const [isReviewing] = useState(false);

  const handleApply = async () => {
    setIsSubmitting(true);
    try {
      await authenticatedFetch("/submit-application", {
        method: "POST",
        body: JSON.stringify({
          user_id: userId,
          internship_id: internship.id,
          cover_letter: coverLetter,
          student_email: studentEmail,
        }),
      });

      setHasApplied(true);
      setApplyModalOpen(false);
      alert(
        "Application submitted successfully! The employer has been notified.",
      );
    } catch (error: unknown) {
      console.error("Application error:", error);
      alert(
        error instanceof Error
          ? error.message
          : "Failed to submit application.",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDraftCoverLetter = async () => {
    setIsDrafting(true);

    // Clear letter only if drafting from scratch
    if (!coverLetter) {
      setCoverLetter("");
    }

    try {
      const response = await authenticatedFetchStream(
        "/draft-cover-letter-stream",
        {
          method: "POST",
          body: JSON.stringify({
            user_id: userId,
            internship_id: internship.id,
            existing_letter: coverLetter,
          }),
        },
      );

      if (!response.body)
        throw new Error("No response body returned from stream.");

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let streamFinished = false;

      // Clear letter before stream starts appending if we are replacing it
      setCoverLetter("");

      while (!streamFinished) {
        const { done, value } = await reader.read();
        if (done) {
          streamFinished = true;
          break;
        }
        if (value) {
          const chunkText = decoder.decode(value, { stream: true });
          setCoverLetter((prev) => prev + chunkText);
        }
      }
    } catch (error: unknown) {
      console.error("Drafting stream error:", error);
      alert(
        error instanceof Error
          ? error.message
          : "An error occurred while drafting the cover letter.",
      );
    } finally {
      setIsDrafting(false);
    }
  };

  const statusConfig: Record<
    string,
    { label: string; icon: LucideIcon; className: string }
  > = {
    accepted: {
      label: "Application Approved",
      icon: CheckCircle2,
      className: "bg-emerald-600 hover:bg-emerald-600",
    },
    rejected: {
      label: "Application Denied",
      icon: X,
      className: "bg-red-500 hover:bg-red-500",
    },
    pending: {
      label: "Application Pending",
      icon: Clock,
      className: "bg-indigo-600 hover:bg-indigo-600",
    },
    applied: {
      label: "Application Pending",
      icon: Clock,
      className: "bg-indigo-600 hover:bg-indigo-600",
    },
  };

  const appStatus = applicationStatus?.toLowerCase() || "";
  const statusData = hasApplied
    ? statusConfig[appStatus] || statusConfig.pending
    : null;

  return (
    <>
      <div className="space-y-2.5">
        {/* Apply / Status Button */}
        <button
          onClick={() => !hasApplied && setApplyModalOpen(true)}
          disabled={hasApplied}
          className={cx(
            "w-full flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-semibold text-white transition-colors",
            hasApplied
              ? cx(
                  "cursor-default opacity-90",
                  statusData?.className || "bg-indigo-600",
                )
              : "bg-slate-800 hover:bg-slate-700",
          )}
        >
          {hasApplied && statusData ? (
            <>
              <statusData.icon className="w-4 h-4" />
              {statusData.label}
            </>
          ) : (
            <>
              <Send className="w-4 h-4" />
              Apply Now
            </>
          )}
        </button>

        {/* AI Review Button */}
        <button
          onClick={() => setCvReviewModalOpen(true)}
          className="w-full flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-medium text-slate-600 bg-slate-50 border border-slate-150 hover:border-slate-300 hover:bg-slate-100 transition-all"
        >
          <Sparkles className="w-4 h-4 text-amber-500" />
          AI CV Review
        </button>
      </div>

      {/* Apply Modal */}
      <Modal
        isOpen={isApplyModalOpen}
        onClose={() => !isSubmitting && setApplyModalOpen(false)}
        title="Apply"
        size="md"
        footer={
          <div className="flex gap-2 w-full">
            <button
              onClick={handleDraftCoverLetter}
              disabled={isDrafting || isSubmitting}
              className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-lg text-sm font-medium text-slate-600 bg-slate-50 border border-slate-200 hover:border-slate-300 disabled:opacity-50 transition-all"
            >
              {isDrafting ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Sparkles className="w-4 h-4 text-amber-500" />
              )}
              {isDrafting
                ? coverLetter.trim()
                  ? "Enhancing..."
                  : "Drafting..."
                : coverLetter.trim()
                  ? "Enhance with AI"
                  : "Draft with AI"}
            </button>
            <button
              onClick={handleApply}
              disabled={isSubmitting || isDrafting}
              className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-lg text-sm font-semibold text-white bg-slate-800 hover:bg-slate-700 disabled:opacity-50 transition-colors"
            >
              {isSubmitting ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Send className="w-4 h-4" />
              )}
              Submit
            </button>
          </div>
        }
      >
        <div className="space-y-4">
          <div className="bg-indigo-50/70 p-4 rounded-lg border border-indigo-100">
            <p className="text-xs font-semibold text-indigo-500 uppercase tracking-wider mb-1">
              Why you?
            </p>
            <p className="text-sm text-slate-600">
              Share a brief statement about why you're interested in this role
              at {internship.company}.
            </p>
          </div>

          <Textarea
            label="Cover Letter"
            placeholder="Tell us about yourself and why you're a good fit..."
            value={coverLetter}
            onChange={(e) => setCoverLetter(e.target.value)}
            disabled={isSubmitting}
            rows={6}
          />
        </div>
      </Modal>

      {/* AI Review Modal */}
      <Modal
        isOpen={isCvReviewModalOpen}
        onClose={() => !isReviewing && setCvReviewModalOpen(false)}
        title="Keyword Analysis"
        size="md"
      >
        <div className="space-y-5">
          <p className="text-sm text-slate-400">
            Your profile compared against the requirements for{" "}
            <span className="font-medium text-slate-600">
              {internship.role || "this position"}
            </span>
            .
          </p>

          <div className="space-y-4">
            {matchingSkills.length > 0 && (
              <div className="bg-emerald-50/60 border border-emerald-100 p-4 rounded-xl space-y-3">
                <div className="flex items-center gap-2 text-emerald-600">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-sm font-semibold">Matched skills</span>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {matchingSkills.map((skill, index) => (
                    <span
                      key={index}
                      className="px-2.5 py-1 bg-emerald-100 text-emerald-700 rounded-md text-xs font-medium"
                    >
                      {skill}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {missingSkills.length > 0 && (
              <div className="bg-amber-50/60 border border-amber-100 p-4 rounded-xl space-y-3">
                <div className="flex items-center gap-2 text-amber-600">
                  <AlertTriangle className="w-4 h-4" />
                  <span className="text-sm font-semibold">
                    Missing keywords
                  </span>
                </div>
                <p className="text-sm text-amber-800/70 leading-relaxed">
                  Recruiters look for{" "}
                  <strong>{missingSkills.join(", ")}</strong>. Consider adding
                  these to your profile if applicable.
                </p>
              </div>
            )}

            {matchingSkills.length === 0 && missingSkills.length === 0 && (
              <div className="bg-slate-50 border border-slate-100 p-6 rounded-xl text-center">
                <p className="text-sm text-slate-400">
                  Resume analysis is still processing or unavailable for this
                  listing.
                </p>
              </div>
            )}

            <button
              onClick={() => setCvReviewModalOpen(false)}
              className="w-full py-2.5 bg-slate-800 text-white rounded-lg text-sm font-semibold hover:bg-slate-700 transition-colors mt-2"
            >
              Got it
            </button>
          </div>
        </div>
      </Modal>
    </>
  );
}

import React from "react";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import Link from "next/link";
import { 
  Briefcase, 
  MapPin, 
  Clock, 
  CalendarDays,
  ArrowLeft,
  CheckCircle2,
  Zap,
  Building2,
  ExternalLink
} from "lucide-react";

import DashboardShell from "@/components/DashboardShell";
import InternshipClientParts from "./InternshipClientParts";
import { supabaseFetch } from "@/lib/supabase-fetch";

export default async function InternshipDetailsPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id: internshipId } = await params;
  const cookieStore = await cookies();

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: { fetch: supabaseFetch },
      cookies: {
        getAll() { return cookieStore.getAll(); },
        setAll() {}
      },
    }
  );

  const { data: { session } } = await supabase.auth.getSession();

  // Fetch internship data
  const { data: internship, error: internshipError } = await supabase
    .from("internships")
    .select("*")
    .eq("id", internshipId)
    .single();

  if (internshipError || !internship) {
    return (
      <div className="min-h-screen bg-[#f9fafb] flex flex-col items-center justify-center p-6 text-center">
        <div className="w-14 h-14 bg-slate-100 rounded-full flex items-center justify-center mb-4">
          <Briefcase className="w-6 h-6 text-slate-300" />
        </div>
        <h2 className="text-lg font-semibold text-slate-800 mb-1">Internship not found</h2>
        <p className="text-sm text-slate-400 mb-6">This listing may have been removed or is no longer available.</p>
        <Link href="/dashboard/student">
          <button className="px-5 py-2.5 bg-slate-800 text-white rounded-lg text-sm font-semibold hover:bg-slate-700 transition-colors">
            Back to Dashboard
          </button>
        </Link>
      </div>
    );
  }

  // Fetch user-specific data if logged in
  let hasApplied = false;
  let applicationStatus: string | null = null;
  let matchScore: number | null = null;
  let matchingSkills: string[] = [];
  let missingSkills: string[] = [];
  let userProfile: any = null;

  if (session) {
    const [appliedRes, matchRes, profileRes] = await Promise.all([
      supabase.from("applied_internships")
        .select("id, status")
        .eq("user_id", session.user.id)
        .eq("internship_id", internshipId)
        .maybeSingle(),
      supabase.from("match_results")
        .select("match_score, matching_skills, missing_skills")
        .eq("user_id", session.user.id)
        .eq("internship_id", internshipId)
        .maybeSingle(),
      supabase.from("profiles")
        .select("*")
        .eq("id", session.user.id)
        .single()
    ]);

    if (appliedRes.data) {
      hasApplied = true;
      applicationStatus = appliedRes.data.status;
    }

    if (matchRes.data) {
      matchScore = matchRes.data.match_score;
      matchingSkills = matchRes.data.matching_skills || [];
      missingSkills = matchRes.data.missing_skills || [];
    }

    userProfile = profileRes.data;
  }

  const requirementsList = Array.isArray(internship.requirements)
    ? internship.requirements
    : internship.requirements?.split("\n").filter(Boolean) || [];

  const responsibilitiesList = Array.isArray(internship.responsibilities)
    ? internship.responsibilities
    : internship.responsibilities?.split("\n").filter(Boolean) || [];

  const displayScore = matchScore !== null ? matchScore : (internship.matchPercentage || 0);

  const daysUntilDeadline = internship.deadline
    ? Math.ceil((new Date(internship.deadline).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))
    : null;

  const matchColor = displayScore >= 70 ? "text-emerald-600" : displayScore >= 40 ? "text-amber-600" : "text-slate-500";
  const matchBg = displayScore >= 70 ? "bg-emerald-50" : displayScore >= 40 ? "bg-amber-50" : "bg-slate-50";

  return (
    <DashboardShell userProfile={userProfile}>
      <div className="max-w-4xl mx-auto px-4 md:px-0 py-6 md:py-10">

        {/* Back link */}
        <Link href="/dashboard/student" className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-slate-600 mb-8 transition-colors group">
          <ArrowLeft className="w-4 h-4 group-hover:-translate-x-0.5 transition-transform" />
          Back to internships
        </Link>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">

            {/* Header */}
            <div>
              <div className="flex items-start justify-between gap-4 mb-3">
                <div>
                  <h1 className="text-2xl font-bold text-slate-800 leading-tight">
                    {internship.role || internship.title}
                  </h1>
                  <div className="flex items-center gap-2 mt-1.5">
                    <Building2 className="w-3.5 h-3.5 text-slate-400" />
                    <span className="text-sm font-medium text-indigo-600">{internship.company}</span>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap gap-2 mt-4">
                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-slate-50 text-slate-600 rounded-md text-xs font-medium border border-slate-100">
                  <Briefcase className="w-3 h-3" /> {internship.category || internship.field || "Internship"}
                </span>
                <span className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-slate-50 text-slate-600 rounded-md text-xs font-medium border border-slate-100">
                  <MapPin className="w-3 h-3" /> {internship.location || "Remote"}
                </span>
                {internship.duration && (
                  <span className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-slate-50 text-slate-600 rounded-md text-xs font-medium border border-slate-100">
                    <Clock className="w-3 h-3" /> {internship.duration}
                  </span>
                )}
                {daysUntilDeadline !== null && (
                  <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-medium border ${
                    daysUntilDeadline > 7 
                      ? "bg-emerald-50 text-emerald-600 border-emerald-100" 
                      : daysUntilDeadline > 0 
                        ? "bg-amber-50 text-amber-600 border-amber-100" 
                        : "bg-red-50 text-red-500 border-red-100"
                  }`}>
                    <CalendarDays className="w-3 h-3" />
                    {daysUntilDeadline > 0 ? `${daysUntilDeadline} days left` : "Deadline passed"}
                  </span>
                )}
              </div>
            </div>

            <hr className="border-slate-100" />

            {/* Description */}
            <section>
              <h3 className="text-sm font-semibold text-slate-800 mb-3">About the role</h3>
              <p className="text-sm text-slate-500 leading-relaxed whitespace-pre-line">
                {internship.description || "No description provided."}
              </p>
            </section>

            {/* Requirements */}
            {requirementsList.length > 0 && (
              <section className="bg-white p-5 rounded-xl border border-slate-100">
                <h3 className="text-sm font-semibold text-slate-800 mb-4">Requirements</h3>
                <ul className="space-y-2.5">
                  {requirementsList.map((req: string, idx: number) => (
                    <li key={idx} className="flex items-start gap-2.5">
                      <CheckCircle2 className="w-4 h-4 text-emerald-500 mt-0.5 shrink-0" />
                      <span className="text-sm text-slate-600">{req}</span>
                    </li>
                  ))}
                </ul>
              </section>
            )}

            {/* Responsibilities */}
            {responsibilitiesList.length > 0 && (
              <section className="bg-white p-5 rounded-xl border border-slate-100">
                <h3 className="text-sm font-semibold text-slate-800 mb-4">What you'll do</h3>
                <ul className="space-y-2.5">
                  {responsibilitiesList.map((res: string, idx: number) => (
                    <li key={idx} className="flex items-start gap-2.5">
                      <Zap className="w-4 h-4 text-indigo-500 mt-0.5 shrink-0" />
                      <span className="text-sm text-slate-600">{res}</span>
                    </li>
                  ))}
                </ul>
              </section>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-4">
            <div className="sticky top-20 space-y-4">

              {/* Match Score Card */}
              <div className="bg-white rounded-xl border border-slate-100 overflow-hidden">
                <div className="p-5 text-center border-b border-slate-50">
                  <p className="text-[10px] font-semibold text-slate-300 uppercase tracking-widest mb-2">Profile match</p>
                  <div className={`text-4xl font-bold ${matchColor}`}>{displayScore}%</div>
                  <div className="w-full h-1.5 bg-slate-100 rounded-full mt-3 overflow-hidden">
                    <div 
                      className={`h-full rounded-full transition-all duration-1000 ${
                        displayScore >= 70 ? "bg-emerald-500" : displayScore >= 40 ? "bg-amber-500" : "bg-slate-300"
                      }`}
                      style={{ width: `${displayScore}%` }}
                    />
                  </div>
                </div>

                <div className="p-5 space-y-3">
                  {session ? (
                    <InternshipClientParts 
                      internship={internship}
                      hasApplied={hasApplied}
                      applicationStatus={applicationStatus}
                      matchingSkills={matchingSkills}
                      missingSkills={missingSkills}
                      userId={session.user.id}
                      studentEmail={session.user.email}
                    />
                  ) : (
                    <Link href="/login/student">
                      <button className="w-full py-2.5 bg-slate-800 text-white rounded-lg text-sm font-semibold hover:bg-slate-700 transition-colors">
                        Sign in to Apply
                      </button>
                    </Link>
                  )}
                </div>
              </div>

              {/* Details Card */}
              <div className="bg-white rounded-xl border border-slate-100 p-4 space-y-3">
                <div className="flex items-center gap-2.5 text-sm">
                  <Clock className="w-4 h-4 text-slate-300" />
                  <span className="text-slate-500">
                    Posted {internship.created_at ? new Date(internship.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "recently"}
                  </span>
                </div>
                <div className="flex items-center gap-2.5 text-sm">
                  <CalendarDays className="w-4 h-4 text-slate-300" />
                  <span className="text-slate-500">
                    Deadline: {internship.deadline ? new Date(internship.deadline).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : "TBD"}
                  </span>
                </div>
                {internship.company_website && (
                  <a href={internship.company_website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2.5 text-sm text-indigo-600 hover:text-indigo-700 transition-colors">
                    <ExternalLink className="w-4 h-4" />
                    Company website
                  </a>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </DashboardShell>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import { Button, Input, Typography } from "@/components/ui";
import { getDashboardPathForRole, getUserRoleProfile } from "@/lib/role-guard";

export default function EmployerLogin() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const router = useRouter();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg("");

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;

      // Verify Employer Role
      if (data.user) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("role")
          .eq("id", data.user.id)
          .single();

        if (profile?.role !== "employer") {
          setErrorMsg("This account is not registered as an Employer.");
          await supabase.auth.signOut();
          setLoading(false);
          return;
        }
      }

      if (data.user) {
        const { role, isAdmin } = await getUserRoleProfile(
          supabase,
          data.user.id,
        );
        const destination = getDashboardPathForRole(role, isAdmin);
        router.push(destination);
      } else {
        router.push("/dashboard/employer");
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof Error ? err.message : "Failed to log in.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white md:bg-[#f8fafc] flex items-center justify-center">
      <div className="w-full max-w-md md:mx-6">
