"use client";
import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";
import {
  Button,
  Typography,
  Stack,
  Input,
} from "@/components/ui";
import { AiOutlineArrowLeft, AiOutlineArrowRight } from "react-icons/ai";
import { FileUpload } from "@/components/application/file-upload/file-upload-base";
import { authenticatedFetch } from "@/lib/api";

// --- Data ---
const courses = ["Computer Science", "Engineering", "Business Administration", "Economics", "Biology", "Chemistry", "Physics", "Mathematics", "Design", "Marketing"];
const levels = ["200", "300", "400", "500"];
const interests = ["Software Development", "Data Science", "Engineering", "Business", "Consulting", "Finance", "Design", "Marketing", "Research", "Healthcare"];

type UploadedFile = {
  id: string;
  name: string;
  type: string;
  size: number;
  progress: number;
  failed?: boolean;
  fileObject?: File;
};

function simulateUploadProgress(file: File, onProgress: (progress: number) => void) {
  let progress = 0;
  const interval = setInterval(() => {
    progress += Math.floor(Math.random() * 8) + 5;
    if (progress > 100) progress = 100;
    onProgress(progress);
    if (progress >= 100) clearInterval(interval);
  }, 25);
}

export default function OnboardingClient({ initialUser }: { initialUser: any }) {
  const [step, setStep] = useState(initialUser ? 2 : 1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [optimisticMessage, setOptimisticMessage] = useState("");
  const [formData, setFormData] = useState({
    name: initialUser?.user_metadata?.full_name || initialUser?.user_metadata?.name || "",
    email: initialUser?.email || "",
    password: initialUser ? "PRE_AUTHENTICATED" : "",
    course: "",
    level: "",
    interests: [] as string[],
    cvFile: null as File | null,
  });
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: "",
    severity: "info" as "success" | "error" | "warning" | "info",
  });
  const router = useRouter();

  const handleInputChange = (field: string, value: string) => setFormData((prev) => ({ ...prev, [field]: value }));
  const handleInterestToggle = (interest: string) => {
    setFormData((prev) => ({
      ...prev,
      interests: prev.interests.includes(interest)
        ? prev.interests.filter((i) => i !== interest)
        : [...prev.interests, interest],
    }));
  };

  const handleDropFiles = (files: FileList) => {
    const pdf = Array.from(files).find(f => f.type === "application/pdf" && f.size <= 5 * 1024 * 1024);
    if (!pdf) {
      setSnackbar({ open: true, message: "Please upload a PDF file under 5MB.", severity: "error" });
      return;
    }
    const id = Math.random().toString();
    setUploadedFiles([{ id, name: pdf.name, type: pdf.type, size: pdf.size, progress: 0, fileObject: pdf }]);
    setFormData(prev => ({ ...prev, cvFile: pdf }));
    simulateUploadProgress(pdf, (progress) => {
      setUploadedFiles(prev => prev.map(f => f.id === id ? { ...f, progress } : f));
    });
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setOptimisticMessage("Creating your profile...");
    try {
      let user_id = initialUser?.id;
      if (!user_id) {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: formData.email,
          password: formData.password,
          options: { emailRedirectTo: `${window.location.origin}/dashboard` },
        });
        if (authError) throw authError;
        user_id = authData?.user?.id;
      }

      const { error: profileError } = await supabase.from("profiles").insert({
        id: user_id,
        full_name: formData.name,
        course: formData.course,
        level: formData.level,
        interests: formData.interests,
        role: "student",
      });
      if (profileError) throw profileError;

      if (formData.cvFile) {
        setOptimisticMessage("Analyzing CV...");
        const bf = new FormData();
        bf.append("user_id", user_id!);
        bf.append("file", formData.cvFile);
        authenticatedFetch("/upload-and-analyze", { method: "POST", body: bf }).catch(console.error);
      }

      setStep(5);
    } catch (err: any) {
      setSnackbar({ open: true, message: err.message, severity: "error" });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="w-full max-w-3xl md:mx-6">
      <div className="px-6 py-8 md:p-12 md:bg-white md:rounded-3xl md:shadow-2xl">
        <div className="mb-10">
          <Typography variant="h2" weight="bold" className="mb-3">
             {step === 1 && "Personal Information"}
             {step === 2 && "Academic Details"}
             {step === 3 && "Select Your Level"}
             {step === 4 && "Career Interests & CV"}
             {step === 5 && "Complete!"}
          </Typography>
          <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden mt-4">
             <div className="h-full bg-brand transition-all duration-500" style={{ width: `${(step/5)*100}%` }} />
          </div>
        </div>

        <div className="min-h-[320px]">
          {step === 1 && (
            <Stack spacing={6}>
              <Input label="Name" value={formData.name} onChange={e => handleInputChange("name",e.target.value)} />
              <Input label="Email" value={formData.email} onChange={e => handleInputChange("email",e.target.value)} />
              <Input label="Password" type="password" value={formData.password} onChange={e => handleInputChange("password",e.target.value)} />
            </Stack>
          )}
          {step === 2 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {courses.map(c => (
                <Button key={c} variant={formData.course === c ? "solid" : "outline"} onClick={() => setFormData({...formData, course: c})}>{c}</Button>
              ))}
            </div>
          )}
          {step === 3 && (
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {levels.map(l => (
                <Button key={l} variant={formData.level === l ? "solid" : "outline"} className="h-20" onClick={() => setFormData({...formData, level: l})}>{l}</Button>
              ))}
            </div>
          )}
          {step === 4 && (
            <Stack spacing={8}>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                 {interests.map(i => (
                   <Button key={i} size="sm" variant={formData.interests.includes(i) ? "solid" : "outline"} onClick={() => handleInterestToggle(i)}>{i}</Button>
                 ))}
              </div>
              <FileUpload.Root>
                 {uploadedFiles.length === 0 && <FileUpload.DropZone onDropFiles={handleDropFiles} accept="application/pdf" />}
                 <FileUpload.List>
                   {uploadedFiles.map(f => (
                     <FileUpload.ListItemProgressBar key={f.id} {...f} size={f.size} onDelete={() => {setUploadedFiles([]); setFormData({...formData, cvFile: null})}} />
                   ))}
                 </FileUpload.List>
              </FileUpload.Root>
            </Stack>
          )}
          {step === 5 && (
            <div className="text-center py-10">
               <Typography variant="h3">You're all set!</Typography>
               <Typography color="muted" className="mt-4">Check your email for verification. You can now proceed to the dashboard.</Typography>
               <Button className="mt-8" onClick={() => router.push("/dashboard/student")}>Go to Dashboard</Button>
            </div>
          )}
        </div>

        {step < 5 && (
          <div className="flex justify-between mt-12 pt-8 border-t border-slate-100">
             {step > 1 && <Button variant="ghost" onClick={() => setStep(step - 1)}>Back</Button>}
             <div className="ml-auto">
                {step < 4 ? (
                  <Button onClick={() => setStep(step +1)} disabled={(step===1 && !formData.name) || (step===2 && !formData.course) || (step===3 && !formData.level)}>Next</Button>
                ) : (
                  <Button onClick={handleSubmit} isLoading={isSubmitting}>{isSubmitting ? optimisticMessage : "Complete Setup"}</Button>
                )}
             </div>
          </div>
        )}
      </div>

      {snackbar.open && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-50 text-red-700 px-6 py-3 rounded-xl border border-red-100 shadow-xl">
           {snackbar.message}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { supabase } from "@/lib/supabaseClient";
import {
  Button,
  Card,
  CardContent,
  CardHeader,
  Input,
  Textarea,
  Typography,
  Stack,
} from "@/components/ui";

const employerSchema = z.object({
  companyName: z.string().min(2, "Company name must be at least 2 characters."),
  email: z.string().email("Please enter a valid work email."),
  password: z.string().min(8, "Password must be at least 8 characters."),
  companyDescription: z.string().min(15, "Please provide a slightly longer description."),
});
type EmployerForm = z.infer<typeof employerSchema>;

export default function EmployerOnboarding() {
  const { register, handleSubmit, formState: { errors } } = useForm<EmployerForm>({
    resolver: zodResolver(employerSchema),
  });
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const router = useRouter();

  const handleRegister = async (data: EmployerForm) => {
    setLoading(true);
    setErrorMsg("");

    try {
      const { email, password, companyName, companyDescription } = data;
      // 1. Create Auth User
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email,
        password,
      });

      if (authError) throw authError;

      // 2. Insert Profile Data
      if (authData.user) {
         const updates = {
            id: authData.user.id,
            full_name: companyName, // Treating Company Name as Full Name for Fallbacks
            company_name: companyName,
            company_description: companyDescription,
            role: "employer",
            updated_at: new Date().toISOString(),
         };

         const { error: profileError } = await supabase.from("profiles").upsert(updates);
         if (profileError) throw profileError;
      }

      router.push("/dashboard/employer");
    } catch (err: any) {
      setErrorMsg(err.message || "Registration failed.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-white md:bg-[#f8fafc] flex items-center justify-center">
      <div className="w-full max-w-xl md:mx-6">
        <div className="px-6 py-10 md:p-10 md:bg-white md:rounded-3xl md:shadow-2xl md:border md:border-slate-100">
          <div className="flex flex-col items-center mb-8">
            <img src="/favicon.ico" alt="PAU Logo" className="w-14 h-14 mb-4 rounded-xl" />
            <Typography variant="h3" weight="bold" className="mb-1">Register Your Company</Typography>
            <Typography variant="body2" color="muted">Create an employer account to post internships and discover talent.</Typography>
          </div>

          {errorMsg && (
            <div className="mb-6 px-4 py-3 rounded-xl bg-red-50 text-red-700 border border-red-100 text-sm font-medium">
              {errorMsg}
            </div>
          )}

          <form onSubmit={handleSubmit(handleRegister)} className="space-y-5">
            <Input
              id="companyName"
              label="Company Name"
              placeholder="Google, Inc."
              error={errors.companyName?.message}
              {...register("companyName")}
            />

            <Input
              id="email"
              label="Work Email Address"
              type="email"
              placeholder="name@company.com"
              error={errors.email?.message}
              {...register("email")}
            />

            <Input
              id="password"
              label="Password"
              type="password"
              placeholder="••••••••"
              error={errors.password?.message}
              {...register("password")}
            />

            <Textarea
              id="companyDescription"
              label="Short Company Description"
              placeholder="Tell us about your company..."
              rows={3}
              error={errors.companyDescription?.message}
              {...register("companyDescription")}
            />

            <Button 
              type="submit" 
              className="w-full !rounded-full" 
              size="lg"
              isLoading={loading}
            >
              Create Account
            </Button>
          </form>

          <Typography variant="body2" className="text-center mt-8">
            Already registered?{" "}
            <span 
              className="text-brand cursor-pointer font-bold hover:underline" 
              onClick={() => router.push("/login/employer")}
            >
              Sign in
            </span>
          </Typography>

          <Button
            variant="ghost"
            onClick={() => router.push("/")}
            className="w-full mt-4 text-xs"
          >
            Back to Home
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabaseClient";
import { Button, Input } from "@/components/ui";
import {
  ArrowLeft,
  Edit2,
  Save,
  Download,
  User,
  UploadCloud,
  CheckCircle2,
  AlertCircle,
  FileText,
  Loader2,
} from "lucide-react";
import { authenticatedFetch, ensureFreshCvUrl } from "@/lib/api";
import { cx } from "@/utils/cx";

type ProfileState = {
  id?: string;
  full_name?: string;
  course?: string;
  level?: string;
  interests?: string[] | string;
  cv_url?: string;
  cvFile?: File;
};

export default function ProfileClient({
  initialProfile,
  userEmail,
}: {
  initialProfile: ProfileState | null;
  userEmail: string | null;
}) {
  const router = useRouter();
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [profile, setProfile] = useState<ProfileState>(initialProfile || {});
  const [status, setStatus] = useState<{
    type: "success" | "error" | "warning";
    message: string;
  } | null>(null);
  const [isRefreshingCv, setIsRefreshingCv] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    setStatus(null);
    try {
      const {
        data: { session },
      } = await supabase.auth.getSession();
      const userId = session?.user?.id;
      if (!userId) throw new Error("Not logged in");

      const { error } = await supabase.from("profiles").upsert({
        id: userId,
        full_name: profile.full_name,
        course: profile.course,
        level: profile.level,
        interests: profile.interests,
        cv_url: profile.cv_url,
      });
      if (error) throw error;

      if (profile.cvFile) {
        setStatus({
          type: "warning",
          message: "Saving changes and starting AI analysis...",
        });
        const bf = new FormData();
        bf.append("user_id", userId);
        bf.append("file", profile.cvFile);
        authenticatedFetch("/upload-and-analyze", {
          method: "POST",
          body: bf,
        }).catch(console.error);
      }

      setStatus({ type: "success", message: "Profile saved successfully!" });
      setIsEditing(false);
    } catch (err: unknown) {
      setStatus({
        type: "error",
        message: err instanceof Error ? err.message : "Failed to save profile",
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      <button
        onClick={() => router.push("/dashboard/student")}
        className="inline-flex items-center gap-2 text-sm text-slate-400 hover:text-slate-600 transition-colors group"
      >
        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-0.5 transition-transform" />
        Back to Dashboard
      </button>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
        {/* Profile Header */}
        <div className="bg-slate-50/50 px-6 py-8 md:px-10 border-b border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex flex-col md:flex-row items-center gap-5">
            <div className="w-20 h-20 bg-white rounded-2xl border border-slate-200 flex items-center justify-center shadow-sm">
              <User className="w-10 h-10 text-slate-300" />
            </div>
            <div className="text-center md:text-left">
              <h1 className="text-xl font-bold text-slate-800">
                {profile.full_name || "Guest User"}
              </h1>
              <p className="text-sm text-slate-400 font-medium">
                {userEmail || "Log in to save"}
              </p>
            </div>
          </div>

          <div className="shrink-0">
            {!isEditing ? (
              <button
                onClick={() => setIsEditing(true)}
                className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-semibold text-slate-700 hover:bg-slate-50 transition-all shadow-sm"
              >
                <Edit2 className="w-3.5 h-3.5" />
                Edit Profile
              </button>
            ) : (
              <button
                disabled={isSaving}
                onClick={handleSave}
                className={cx(
                  "flex items-center gap-2 px-5 py-2 bg-slate-800 rounded-lg text-sm font-semibold text-white hover:bg-slate-700 transition-all shadow-sm",
                  isSaving && "opacity-50 cursor-not-allowed",
                )}
              >
                {isSaving ? (
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                ) : (
                  <Save className="w-3.5 h-3.5" />
                )}
                Save Changes
              </button>
            )}
          </div>
        </div>

        <div className="p-6 md:p-10 space-y-10">
          {status && (
            <div
              className={cx(
                "p-4 rounded-xl flex items-center gap-3 text-sm font-medium",
                status.type === "success"
                  ? "bg-emerald-50 text-emerald-700 border border-emerald-100"
                  : status.type === "warning"
                    ? "bg-amber-50 text-amber-700 border border-amber-100"
                    : "bg-rose-50 text-rose-700 border border-rose-100",
              )}
            >
              {status.type === "success" ? (
                <CheckCircle2 className="w-4 h-4" />
              ) : (
                <AlertCircle className="w-4 h-4" />
              )}
              <span>{status.message}</span>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-widest px-1">
                Full Name
              </label>
              <Input
                placeholder="Ex. Hillary Ilona"
                value={profile.full_name || ""}
                onChange={(e) =>
                  setProfile({ ...profile, full_name: e.target.value })
                }
                disabled={!isEditing}
                className="bg-transparent border-slate-150 rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-widest px-1">
                Email address
              </label>
              <Input
                value={userEmail || ""}
                disabled={true}
                className="bg-slate-50/50 border-slate-150 rounded-xl opacity-60"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[11px] font-bold text-slate-400 uppercase tracking-widest px-1">
              Course of Study
            </label>
            <Input
              placeholder="Ex. Computer Science"
              value={profile.course || ""}
              onChange={(e) =>
                setProfile({ ...profile, course: e.target.value })
              }
              disabled={!isEditing}
              className="bg-transparent border-slate-150 rounded-xl"
            />
          </div>

          <hr className="border-slate-100" />

          <div className="space-y-6">
            <h3 className="text-sm font-bold text-slate-800">
              Curriculum Vitae (CV)
            </h3>
            <div className="bg-slate-50/50 border border-slate-150 border-dashed rounded-2xl p-8 flex flex-col items-center text-center">
              <div className="w-12 h-12 bg-white rounded-xl border border-slate-100 flex items-center justify-center mb-4 shadow-sm">
                <FileText className="w-6 h-6 text-indigo-500" />
              </div>
              <p className="text-sm font-bold text-slate-700 mb-1">
                {profile.cvFile
                  ? profile.cvFile.name
                  : profile.cv_url
                    ? "Current CV Document"
                    : "No CV uploaded"}
              </p>
              <p className="text-xs text-slate-400 mb-6">
                Upload a professional PDF version of your CV for AI analysis
              </p>

              <div className="flex flex-wrap items-center justify-center gap-3">
                <label
                  className={cx(
                    "flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-semibold text-slate-700 hover:bg-slate-50 transition-all shadow-sm cursor-pointer",
                    !isEditing &&
                      "opacity-50 cursor-not-allowed pointer-events-none",
                  )}
                >
                  <UploadCloud className="w-3.5 h-3.5 text-indigo-500" />
                  {profile.cvFile ? "Change File" : "Upload CV"}
                  <input
                    type="file"
                    hidden
                    accept=".pdf"
                    onChange={(e) => {
                      if (e.target.files?.[0])
                        setProfile({ ...profile, cvFile: e.target.files?.[0] });
                    }}
                  />
                </label>

                {profile.cv_url && (
                  <button
                    disabled={isRefreshingCv}
                    onClick={async () => {
                      // 1. Open blank window immediately to satisfy popup blocker requirements
                      const popup = window.open("about:blank", "_blank");
                      if (!popup) {
                        setStatus({
                          type: "error",
                          message:
                            "Popup blocked. Please allow popups for this site.",
                        });
                        return;
                      }

                      setIsRefreshingCv(true);
                      try {
                        const userId = profile.id;
                        if (!userId) {
                          popup.close();
                          setStatus({
                            type: "error",
                            message: "Missing user id; cannot load CV.",
                          });
                          return;
                        }
                        if (!profile.cv_url) {
                          popup.close();
                          setStatus({
                            type: "error",
                            message: "No CV URL found for this profile.",
                          });
                          return;
                        }
                        const freshUrl = await ensureFreshCvUrl(
                          userId,
                          profile.cv_url,
                        );

                        const rawFullName = profile.full_name || "Student";
                        const safeName =
                          rawFullName.trim().replace(/\s+/g, "_") + " CV";
                        const viewerUrl = `/cv/view?name=${encodeURIComponent(safeName)}&url=${encodeURIComponent(freshUrl)}`;

                        // 2. Set the location of the already-opened window
                        popup.location.href = viewerUrl;
                      } catch (err: unknown) {
                        console.error("CV view error:", err);
                        popup.close();
                        setStatus({
                          type: "error",
                          message:
                            "Failed to load CV: " +
                            (err instanceof Error
                              ? err.message
                              : "Unknown error"),
                        });
                      } finally {
                        setIsRefreshingCv(false);
                      }
                    }}
                    className={cx(
                      "flex items-center gap-2 px-4 py-2 bg-slate-800 rounded-lg text-sm font-semibold text-white hover:bg-slate-700 transition-all shadow-sm",
                      isRefreshingCv && "opacity-50 cursor-not-allowed",
                    )}
                  >
                    {isRefreshingCv ? (
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    ) : (
                      <Download className="w-3.5 h-3.5" />
                    )}
                    {isRefreshingCv ? "Refreshing..." : "View Current"}
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { LogOut, User, Briefcase, BookOpen } from "lucide-react";
import { supabase } from "@/lib/supabaseClient";
import { Button, Typography, Stack } from "@/components/ui";

interface DashboardHeaderProps {
  userProfile?: any;
}

const DashboardHeader = ({ userProfile }: DashboardHeaderProps) => {
  const router = useRouter();
  const [isLoggingOut, setIsLoggingOut] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [notificationMessage, setNotificationMessage] = useState("");
  const [notificationSeverity, setNotificationSeverity] = useState<"success" | "error" | "info" | "warning">("info");

  const isEmployer = userProfile?.role === "employer";

  const handleLogout = async () => {
    if (isLoggingOut) return;
    setIsLoggingOut(true);
    setNotificationMessage("Logging out...");
    setNotificationSeverity("info");
    setNotificationOpen(true);

    try {
      // 1. Sign out from Supabase client (requires active session token in storage)
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("Supabase signOut error:", err);
    }

    try {
      // 2. Clear cookies on the server
      await fetch("/api/auth/logout", { method: "POST" });
    } catch (err) {
      console.warn("Server cookie logout error:", err);
    }

    // 3. Wreak havoc on other local storage entries
    localStorage.clear();

    window.location.href = isEmployer ? "/login/employer" : "/login/student";
  };

  const displayName = isEmployer 
    ? (userProfile?.company_name || "Employer") 
    : (userProfile?.name?.split(" ")[0] || userProfile?.full_name?.split(" ")[0] || userProfile?.email || "Student");

  return (
    <>
      <header className="sticky top-0 z-50 bg-white/90 backdrop-blur-sm border-b border-slate-100 h-14 flex items-center">
        <div className="max-w-7xl w-full mx-auto px-4 md:px-6 flex justify-between items-center">
          <div 
            className="flex items-center gap-3 cursor-pointer group" 
            onClick={() => router.push(isEmployer ? "/dashboard/employer" : "/dashboard/student")}
          >
            <div className="w-8 h-8 bg-slate-800 rounded-lg flex items-center justify-center p-1.5 group-hover:scale-105 transition-transform">
              <img src="/favicon.ico" alt="PAU Logo" className="w-full h-full brightness-0 invert" />
            </div>
            <div className="hidden sm:block">
              <p className="text-sm font-semibold text-slate-800 leading-none">InterConnect</p>
              <p className="text-[11px] text-slate-400 mt-0.5">
                Hi, <span className="font-semibold text-slate-600">{displayName}</span>
              </p>
            </div>
          </div>

          <div className="flex items-center gap-1">
            <div className="flex items-center gap-0.5 bg-slate-50 p-0.5 rounded-lg border border-slate-100">
              {!isEmployer && (
                <>
                  <button
                    onClick={() => router.push("/my-internships")}
                    className="w-8 h-8 flex items-center justify-center rounded-md text-slate-400 hover:text-slate-600 hover:bg-white transition-all"
                    title="My Internships"
                  >
                    <Briefcase className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => router.push("/dashboard/student/logbook")}
                    className="w-8 h-8 flex items-center justify-center rounded-md text-slate-400 hover:text-slate-600 hover:bg-white transition-all"
                    title="Logbook"
                  >
                    <BookOpen className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => router.push("/profile")}
                    className="w-8 h-8 flex items-center justify-center rounded-md text-slate-400 hover:text-slate-600 hover:bg-white transition-all"
                    title="Profile"
                  >
                    <User className="w-4 h-4" />
                  </button>
                </>
              )}
              <button
                onClick={handleLogout}
                disabled={isLoggingOut}
                className={`w-8 h-8 flex items-center justify-center rounded-md transition-all ${isLoggingOut ? 'opacity-50 cursor-not-allowed text-red-400' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`}
                title="Logout"
              >
                {isLoggingOut ? (
                  <div className="w-4 h-4 rounded-full border-2 border-red-400 border-t-transparent animate-spin" />
                ) : (
                  <LogOut className="w-4 h-4" />
                )}
              </button>
            </div>
          </div>
        </div>

        {notificationOpen && (
          <div className={`fixed top-4 left-1/2 -translate-x-1/2 px-4 py-2 rounded-lg shadow-lg animate-in slide-in-from-top-4 duration-300 z-[100] text-sm font-medium ${
            notificationSeverity === "success" 
              ? "bg-emerald-50 text-emerald-700 border border-emerald-100" 
              : "bg-slate-50 text-slate-700 border border-slate-200"
          }`}>
            {notificationMessage}
          </div>
        )}
      </header>
    </>
  );
};

export default DashboardHeader;

"use client";
import React, { useState } from "react";
import Sidebar from "./Sidebar";
import TopBar from "./TopBar";
import { cx } from "@/utils/cx";

interface DashboardShellProps {
  children: React.ReactNode;
  userProfile?: any;
  searchQuery?: string;
  onSearchChange?: (val: string) => void;
  className?: string;
}

const DashboardShell = ({ 
  children, 
  userProfile, 
  searchQuery, 
  onSearchChange,
  className 
}: DashboardShellProps) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPinned, setIsPinned] = useState(false);

  return (
    <div className="flex min-h-screen bg-[#f9fafb]">
      {/* Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden animate-in fade-in duration-300"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar - Desktop: Mini/Full, Mobile: Drawer */}
      <Sidebar 
        userProfile={userProfile}
        onClose={() => setIsSidebarOpen(false)}
        isPinned={isPinned}
        onTogglePin={() => setIsPinned(!isPinned)}
        className={cx(
          "fixed inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out",
          isSidebarOpen ? "translate-x-0 w-72" : "-translate-x-full lg:translate-x-0"
        )}
      />

      {/* Main Content Area */}
      <div className={cx(
        "flex-1 flex flex-col min-w-0 transition-all duration-[400ms] ease-in-out",
        isPinned ? "lg:pl-72" : "lg:pl-20"
      )}>
        <TopBar 
          onMenuClick={() => setIsSidebarOpen(true)}
          searchQuery={searchQuery}
          onSearchChange={onSearchChange}
          userProfile={userProfile}
        />

        <main className={cx(
          "flex-1 p-4 md:p-8 overflow-y-auto max-w-7xl mx-auto w-full",
          className
        )}>
          {children}
        </main>
      </div>
    </div>
  );
};

