"use client";

import { useState, useEffect } from "react";
import { BookOpen, CheckCircle2, AlertTriangle, X } from "lucide-react";
import Link from "next/link";

interface LogbookWidgetClientProps {
  isMissing: boolean;
  todayStatus: string | null;
}

export default function LogbookWidgetClient({
  isMissing,
  todayStatus,
}: LogbookWidgetClientProps) {
  const [isVisible, setIsVisible] = useState(true);

  // Persistence within the same day
  useEffect(() => {
    try {
      const todayStr = new Date().toISOString().split("T")[0];
      const dismissed = localStorage.getItem(`logbook_reminder_dismissed_${todayStr}`);
      if (dismissed === "true") {
        setIsVisible(false);
      }
    } catch (e) {
      console.warn("localStorage is not available:", e);
    }
  }, []);

  const handleDismiss = () => {
    try {
      const todayStr = new Date().toISOString().split("T")[0];
      localStorage.setItem(`logbook_reminder_dismissed_${todayStr}`, "true");
    } catch (e) {
      console.warn("Failed to set localStorage:", e);
    }
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div
      className={`relative flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-4 pr-12 rounded-2xl border transition-all duration-300 animate-in fade-in slide-in-from-top-2 ${
        isMissing
          ? "bg-amber-50/60 border-amber-100/80 shadow-[0_2px_8px_rgba(245,158,11,0.04)]"
          : "bg-emerald-50/60 border-emerald-100/80 shadow-[0_2px_8px_rgba(16,185,129,0.04)]"
      }`}
    >
      <div className="flex items-center gap-3">
        <div
          className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${
            isMissing
              ? "bg-amber-100/80 text-amber-600"
              : "bg-emerald-100/80 text-emerald-600"
          }`}
        >
          {isMissing ? (
            <AlertTriangle className="w-4 h-4" />
          ) : (
            <CheckCircle2 className="w-4 h-4" />
          )}
        </div>
        <div>
          <p className="text-sm font-bold text-slate-800">
            {isMissing ? "Today's log is missing" : "Today's log submitted"}
          </p>
          <p className="text-xs text-slate-500 mt-0.5 font-medium">
            {isMissing
              ? "Record your progress in the logbook before the end of the day"
              : `Status: ${todayStatus}`}
          </p>
        </div>
      </div>

      <div className="flex items-center gap-2 shrink-0">
        <Link href="/dashboard/student/logbook" className="no-underline">
          <button
            className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold transition-all duration-200 ${
              isMissing
                ? "bg-amber-600 text-white hover:bg-amber-700 shadow-lg shadow-amber-600/10 active:scale-95"
                : "bg-white text-slate-700 border border-slate-200 hover:border-slate-300 hover:bg-slate-50 active:scale-95"
            }`}
          >
            <BookOpen className="w-3.5 h-3.5" />
            Open Logbook
          </button>
        </Link>
      </div>

      <button
        onClick={handleDismiss}
        className="absolute top-1/2 -translate-y-1/2 right-4 p-1.5 rounded-lg text-slate-400 hover:text-slate-600 hover:bg-slate-100/80 transition-all active:scale-90"
        aria-label="Close reminder"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from "react";
import { FiSearch, FiX, FiBriefcase, FiArrowRight } from "react-icons/fi";
import { Typography, Stack, Badge } from "@/components/ui";
import { authenticatedFetch } from "@/lib/api";

type SearchStudent = {
  id: string;
  full_name?: string;
  course?: string;
};

type SearchEmployer = {
  id: string;
  company_name?: string;
  full_name?: string;
};

type SearchInternship = {
  id: string;
  role?: string;
  company?: string;
};

type SearchResults = {
  students?: SearchStudent[];
  employers?: SearchEmployer[];
  internships?: SearchInternship[];
};

interface SearchOverlayProps {
  onClose: () => void;
}

export default function SearchOverlay({ onClose }: SearchOverlayProps) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<SearchResults | null>(null);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [onClose]);

  useEffect(() => {
    const delayDebounceFn = setTimeout(() => {
      if (query.length >= 2) {
        performSearch();
      } else {
        setResults(null);
      }
    }, 300);

    return () => clearTimeout(delayDebounceFn);
  }, [query]);

  const performSearch = async () => {
    try {
      setLoading(true);
      const data = await authenticatedFetch<SearchResults>(
        `/admin/search?q=${encodeURIComponent(query)}`,
      );
      setResults(data);
    } catch (err) {
      console.error("Search failed:", err);
    } finally {
      setLoading(false);
    }
  };

  const hasResults =
    !!results &&
    ((results.students?.length || 0) > 0 ||
      (results.employers?.length || 0) > 0 ||
      (results.internships?.length || 0) > 0);

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[10vh] px-4 backdrop-blur-md bg-slate-900/40 animate-in fade-in duration-200">
      <div
        className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl border border-slate-100 overflow-hidden animate-in slide-in-from-top-4 duration-300"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search Input Container */}
        <div className="p-6 border-b border-slate-100 flex items-center gap-4">
          <FiSearch className="w-6 h-6 text-indigo-500" />
          <input
            ref={inputRef}
            type="text"
            placeholder="Search for students, companies, or internships..."
            className="flex-1 bg-transparent border-none outline-none text-xl font-medium text-slate-800 placeholder:text-slate-400"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          <button
            onClick={onClose}
            className="p-2 hover:bg-slate-100 rounded-xl transition-colors text-slate-400 hover:text-slate-600"
          >
            <FiX className="w-5 h-5" />
          </button>
        </div>

        {/* Results Area */}
        <div className="max-h-[60vh] overflow-y-auto p-2 custom-scrollbar">
          {loading ? (
            <div className="p-12 text-center">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-500"></div>
              <Typography variant="body2" color="muted" className="mt-4">
                Searching platform data...
              </Typography>
            </div>
          ) : !query || query.length < 2 ? (
            <div className="p-12 text-center opacity-50">
              <FiSearch className="w-12 h-12 mx-auto mb-4 text-slate-300" />
              <Typography variant="body1" weight="medium">
                Enter at least 2 characters to search
              </Typography>
              <Typography
                variant="caption"
                color="muted"
                className="mt-2 flex items-center justify-center gap-1"
              >
                Tip: Press{" "}
                <span className="px-1.5 py-0.5 bg-slate-100 rounded border border-slate-200 text-[10px] font-bold">
                  ESC
                </span>{" "}
                to close
              </Typography>
            </div>
          ) : !hasResults ? (
            <div className="p-12 text-center">
              <Typography variant="body1" color="muted">
                No results found for "{query}"
              </Typography>
            </div>
          ) : (
            <div className="p-2 space-y-6">
              {/* Students Section */}
              {(results?.students || []).length > 0 && (
                <div className="space-y-2">
                  <div className="px-4 py-1 flex items-center justify-between">
                    <Typography
                      variant="caption"
                      weight="extrabold"
                      color="muted"
                      className="uppercase tracking-widest"
                    >
                      Students
                    </Typography>
                    <Badge variant="emerald" size="sm">
                      {(results.students || []).length}
                    </Badge>
                  </div>
                  {(results.students || []).map((stu) => (
                    <div
                      key={stu.id}
                      className="p-4 hover:bg-slate-50 rounded-2xl transition-colors cursor-pointer group flex items-center justify-between"
                    >
                      <Stack direction="row" spacing={4} align="center">
                        <div className="w-10 h-10 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center font-bold">
                          {stu.full_name?.[0] || "S"}
                        </div>
                        <div>
                          <Typography weight="bold">
                            {stu.full_name || "Unnamed Student"}
                          </Typography>
                          <Typography variant="caption" color="muted">
                            {stu.course || "General Studies"}
                          </Typography>
                        </div>
                      </Stack>
                      <FiArrowRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-500 group-hover:translate-x-1 transition-all" />
                    </div>
                  ))}
                </div>
              )}

              {/* Employers Section */}
              {(results?.employers || []).length > 0 && (
                <div className="space-y-2">
                  <div className="px-4 py-1 flex items-center justify-between">
                    <Typography
                      variant="caption"
                      weight="extrabold"
                      color="muted"
                      className="uppercase tracking-widest"
                    >
                      Companies
                    </Typography>
                    <Badge variant="indigo" size="sm">
                      {(results.employers || []).length}
                    </Badge>
                  </div>
                  {(results.employers || []).map((emp) => (
                    <div
                      key={emp.id}
                      className="p-4 hover:bg-slate-50 rounded-2xl transition-colors cursor-pointer group flex items-center justify-between"
                    >
                      <Stack direction="row" spacing={4} align="center">
                        <div className="w-10 h-10 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold">
                          {emp.company_name?.[0] || "C"}
                        </div>
                        <div>
                          <Typography weight="bold">
                            {emp.company_name || "Unnamed Company"}
                          </Typography>
                          <Typography variant="caption" color="muted">
                            {emp.full_name || "Contact Rep"}
                          </Typography>
                        </div>
                      </Stack>
                      <FiArrowRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-500 group-hover:translate-x-1 transition-all" />
                    </div>
                  ))}
                </div>
              )}

              {/* Internships Section */}
              {(results?.internships || []).length > 0 && (
                <div className="space-y-2">
                  <div className="px-4 py-1 flex items-center justify-between">
                    <Typography
                      variant="caption"
                      weight="extrabold"
                      color="muted"
                      className="uppercase tracking-widest"
                    >
                      Internships
                    </Typography>
                    <Badge variant="pink" size="sm">
                      {(results.internships || []).length}
                    </Badge>
                  </div>
                  {(results.internships || []).map((job) => (
                    <div
                      key={job.id}
                      className="p-4 hover:bg-slate-50 rounded-2xl transition-colors cursor-pointer group flex items-center justify-between"
                    >
                      <Stack direction="row" spacing={4} align="center">
                        <div className="w-10 h-10 rounded-lg bg-pink-50 text-pink-500 flex items-center justify-center">
                          <FiBriefcase className="w-5 h-5" />
                        </div>
                        <div>
                          <Typography weight="bold">
                            {job.role || "Untitled Role"}
                          </Typography>
                          <Typography variant="caption" color="muted">
                            {job.company || "Unknown Company"}
                          </Typography>
                        </div>
                      </Stack>
                      <FiArrowRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-500 group-hover:translate-x-1 transition-all" />
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between px-6">
          <div className="flex items-center gap-4 text-[11px] font-bold text-slate-400 uppercase tracking-widest">
            <span className="flex items-center gap-1.5">
              <span className="px-1 py-0.5 bg-white rounded border border-slate-200">
                ↑↓
              </span>{" "}
              Navigate
            </span>
            <span className="flex items-center gap-1.5">
              <span className="px-1 py-0.5 bg-white rounded border border-slate-200">
                Enter
              </span>{" "}
              Select
            </span>
          </div>
        </div>
      </div>

      {/* Click outside to close */}
      <div className="absolute inset-0 -z-10" onClick={onClose}></div>
    </div>
  );
}

"use client";
import React from "react";
import { useRouter, usePathname } from "next/navigation";
import { Home, Briefcase, BookOpen, User, Settings, X, ChevronLeft, ChevronRight, BarChart3 } from "lucide-react";
import { Typography } from "./ui";
import { cx } from "@/utils/cx";
import { useState } from "react";

interface SidebarProps {
  userProfile?: any;
  onClose?: () => void;
  isPinned?: boolean;
  onTogglePin?: () => void;
  className?: string;
}

const Sidebar = ({ userProfile, onClose, isPinned, onTogglePin, className }: SidebarProps) => {
  const router = useRouter();
  const pathname = usePathname();
  const [isHovered, setIsHovered] = useState(false);

  const isExpanded = isPinned || isHovered;
  const isEmployer = userProfile?.role === "employer";
  const isAdmin = userProfile?.role === "admin";

  const studentItems = [
    { label: "Home", icon: Home, href: "/dashboard/student" },
    { label: "My Internships", icon: Briefcase, href: "/my-internships" },
    { label: "Skill Gap Analysis", icon: BarChart3, href: "/dashboard/student/skills" },
    { label: "SIWES Logbook", icon: BookOpen, href: "/dashboard/student/logbook" },
  ];

  const employerItems = [
    { label: "Company Home", icon: Home, href: "/dashboard/employer" },
    { label: "My Postings", icon: Briefcase, href: "/dashboard/employer/internships" },
    { label: "Review Logbooks", icon: BookOpen, href: "/dashboard/employer/logbook" },
  ];

  const adminItems = [
    { label: "Admin Home", icon: Home, href: "/dashboard/admin" },
    { label: "Manage Roles", icon: User, href: "/dashboard/admin/manage" },
    { label: "Analytics", icon: BarChart3, href: "/dashboard/admin/analytics" },
  ];

  const dashboardItems = isEmployer ? employerItems : (isAdmin ? adminItems : studentItems);

  const accountItems = [
    { label: isEmployer ? "Company Public Page" : "Profile", icon: User, href: isEmployer ? `/companies/${userProfile?.id}` : "/profile", disabled: isEmployer && !userProfile?.id },
    { label: "Settings", icon: Settings, href: isEmployer ? "/dashboard/employer/settings" : "/dashboard/student/settings", disabled: false },
  ];


  return (
    <aside 
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={cx(
        "flex flex-col h-full bg-white border-r border-slate-100 transition-all duration-[400ms] ease-in-out overflow-hidden",
        isExpanded ? "w-72" : "w-20",
        className
      )}
    >
      {/* Sidebar Header */}
      <div className="py-6 px-5 flex items-center h-20 shrink-0 transition-all duration-[400ms] ease-in-out relative">
        <div 
          className="flex items-center gap-3 cursor-pointer group shrink-0"
          onClick={() => router.push(isEmployer ? "/dashboard/employer" : "/dashboard/student")}
        >
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center p-2 shadow-sm group-hover:scale-105 transition-transform shrink-0">
            <img src="/favicon.ico" alt="PAU Logo" className="w-full h-full brightness-0 invert" />
          </div>
          <div className={cx(
            "transition-all duration-[400ms] ease-in-out overflow-hidden flex items-center",
            isExpanded ? "opacity-100 max-w-[200px]" : "opacity-0 max-w-0"
          )}>
            <span className="text-[15px] font-bold text-slate-800 tracking-tight whitespace-nowrap ml-1">
              InterConnect
            </span>
          </div>
        </div>

        <div className={cx(
          "absolute right-4 flex items-center gap-1 transition-all duration-[400ms] ease-in-out overflow-hidden",
          isExpanded ? "opacity-100 max-w-[200px]" : "opacity-0 max-w-0"
        )}>
          <button 
            onClick={onTogglePin}
            className={cx(
              "p-2 rounded-lg transition-all duration-200 hidden lg:flex items-center justify-center",
              isPinned ? "bg-slate-100 text-slate-600" : "text-slate-300 hover:text-slate-500 hover:bg-slate-50"
            )}
            title={isPinned ? "Unpin sidebar" : "Pin sidebar"}
          >
            {isPinned ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>
          {onClose && (
            <button onClick={onClose} className="lg:hidden p-2 text-slate-400 hover:text-slate-600 transition-colors">
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 flex flex-col px-3 py-4 space-y-8 overflow-y-auto no-scrollbar">
        {/* Dashboard Section */}
        <div>
          <div className="px-5 mb-3 h-4 flex items-center">
            <div className={cx(
              "transition-all duration-[400ms] ease-in-out overflow-hidden flex items-center",
              isExpanded ? "opacity-100 max-w-[200px]" : "opacity-0 max-w-0"
            )}>
              <span className="text-[10px] font-semibold text-slate-300 uppercase tracking-widest whitespace-nowrap">
                Dashboard
