"use client";

import { createContext, useContext, useEffect, useState } from "react";
import { User } from "@supabase/supabase-js";
import { supabase } from "@/lib/supabaseClient";

interface AuthState {
  user: User | null;
  profile: any | null;
  loading: boolean;
}

const AuthContext = createContext<AuthState>({
  user: null,
  profile: null,
  loading: true,
});

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Safeguard: Force loading to false after 10 seconds max if Supabase hangs
    const safetyTimeout = setTimeout(() => {
      setLoading(false);
    }, 10000);

    let isMounted = true;

    // Trigger initial session check immediately in case onAuthStateChange is delayed
    const checkInitialSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (isMounted && session?.user) {
        // This will trigger the logic to fetch profile and set user
        // We actually just need to wait for onAuthStateChange usually, 
        // but if it's already stale, we force it.
      } else if (isMounted && !session) {
        setLoading(false); // No session, stop loading
      }
    };
    checkInitialSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        try {
          if (session?.user) {
            if (user?.id !== session.user.id) {
              setUser(session.user);

              // Simple retry logic for transient network/socket errors
              let attempts = 0;
              let profileData = null;
              let profileError = null;

              while (attempts < 2) {
                const { data, error } = await supabase
                  .from("profiles")
                  .select("*")
                  .eq("id", session.user.id)
                  .maybeSingle();

                if (!error) {
                  profileData = data;
                  break;
                }

                profileError = error;
                attempts++;
                if (attempts < 2) await new Promise(r => setTimeout(r, 1000)); // wait 1s before retry
              }

              if (profileError && Object.keys(profileError).length > 0) {
                console.warn("Profile fetch issue (likely transient):", profileError.message || JSON.stringify(profileError));
              }

              if (isMounted) setProfile(profileData);
            }
          } else {
            if (isMounted) {
              setUser(null);
              setProfile(null);
            }
          }
        } catch (err) {
          // Swallow common refresh errors
        } finally {
          clearTimeout(safetyTimeout);
          if (isMounted) setLoading(false);
        }
      }
    );

    return () => {
      isMounted = false;
      clearTimeout(safetyTimeout);
      subscription.unsubscribe();
    };
  }, []);

  return (
    <AuthContext.Provider value={{ user, profile, loading }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  return useContext(AuthContext);
};

import crossFetch from "cross-fetch";

// Shared custom fetch wrapper to reliably suppress "refresh_token_not_found" error logs 
// which otherwise spam the console randomly during server-side renders or token expirations.
export const supabaseFetch = async (input: RequestInfo | URL, init?: RequestInit) => {
  try {
    const fetchToUse = typeof fetch !== "undefined" ? fetch : crossFetch;
    const res = await fetchToUse(input, init);

    if (res.ok) return res;

    const status = res.status || 0;
    let body: string | null = null;

    // Only clone and read the body if there's an error to log or check
    if (!res.ok) {
      try {
        body = await res.clone().text();
      } catch (e) {
        body = "<unavailable>";
      }
    }

    const isRefreshTokenError = status === 400 && body?.includes("refresh_token_not_found");

    if (!isRefreshTokenError) {
      const meta = {
        url: String(input),
        status,
        statusText: res.statusText,
        init,
        body,
      };

      if (status >= 500) console.error("[Supabase fetch] Server error", meta);
      else if (status >= 400)
        console.warn("[Supabase fetch] Client auth error (suppressed if refresh token missing)", meta);
    }

    return res;
  } catch (err) {
    console.error("[Supabase fetch] Network error for", String(input), err);
    throw err;
  }
};

import { createServerClient, type CookieOptions } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'
import { supabaseFetch } from './lib/supabase-fetch'

export async function proxy(request: NextRequest) {
  let response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      global: { fetch: supabaseFetch },
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value, options }) => request.cookies.set(name, value))
          response = NextResponse.next({
            request: {
              headers: request.headers,
            },
          })
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  try {
    // getUser validates with the server, which is essential for production-grade security.
    await supabase.auth.getUser()
  } catch (err) {
    // Silently handle
  }

  return response

}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon file)
     * Feel free to modify this pattern to include more paths.
     */
    '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
  ],
}
